  3→using Microsoft.Extensions.Logging;
  4→using Microsoft.Extensions.Logging.Abstractions;
  5→using Microsoft.Extensions.Options;
  6→using Ray.Automerge.Repo.Network.SignalR;
  7→using Ray.Automerge.Repo.Network.SignalR.Client;
  8→using Ray.Automerge.Repository;
  9→using Ray.Automerge.Repository.Network;
 10→using Ray.Automerge.Repository.Storage.FileSystem;
 11→
 12→namespace DemoApp.Shared;
 13→
 14→/// <summary>
 15→/// Lifecycle manager for Repo + SignalRNetworkAdapter + FileSystemStorageAdapter.
 16→/// Provides a single entry point for demo apps to set up collaborative document sync.
 17→/// </summary>
 18→[PublicAPI]
 19→public sealed class RepoService : IDisposable
 20→{
 21→  readonly RepoServiceOptions _options;
 22→  readonly ILoggerFactory _loggerFactory;
 23→  readonly ILogger<RepoService> _logger;
 24→
 25→  FileSystemStorageAdapter? _storage;
 26→  SignalRConnectionService? _connectionService;
 27→  SignalRNetworkAdapter? _networkAdapter;
 28→  Repo? _repo;
 29→  ConnectionState _connectionState = ConnectionState.Disconnected;
 30→  int _peerCount;
 31→  bool _disposed;
 32→
 33→  /// <summary>
 34→  /// Initializes a new instance of the <see cref="RepoService"/> class.
 35→  /// </summary>
 36→  /// <param name="options">Configuration options.</param>
 37→  /// <param name="loggerFactory">Optional logger factory. Uses <see cref="NullLoggerFactory"/> if null.</param>
 38→  public RepoService(RepoServiceOptions options, ILoggerFactory? loggerFactory = null)
 39→  {
 40→    ArgumentNullException.ThrowIfNull(options);
 41→    _options = options;
 42→    _loggerFactory = loggerFactory ?? NullLoggerFactory.Instance;
 43→    _logger = _loggerFactory.CreateLogger<RepoService>();
 44→  }
 45→
 46→  /// <summary>
 47→  /// Gets the peer ID of this repo instance. Null before initialization.
 48→  /// </summary>
 49→  public PeerId? PeerId => _repo?.PeerId;
 50→
 51→  /// <summary>
 52→  /// Gets the current connection state to the SignalR hub.
 53→  /// </summary>
 54→  public ConnectionState ConnectionState => _connectionState;
 55→
 56→  /// <summary>
 57→  /// Gets the number of currently connected peers.
 58→  /// </summary>
 59→  public int PeerCount => _peerCount;
 60→
 61→  /// <summary>
 62→  /// Gets the underlying <see cref="Repo"/> instance. Null before initialization.
 63→  /// </summary>
 64→  public Repo? Repo => _repo;
 65→
 66→  /// <summary>
 67→  /// Gets whether the service has been initialized.
 68→  /// </summary>
 69→  public bool IsInitialized => _repo is not null;
 70→
 71→  /// <summary>
 72→  /// Gets the resolved storage directory path.
 73→  /// </summary>
 74→  public string StorageDirectory =>
 75→    _options.StorageBaseDir
 76→    ?? Path.Combine(
 77→      Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),
 78→      ".rayautomerge",
 79→      _options.AppName);
 80→
 81→  /// <summary>
 82→  /// Raised when the connection state changes.
 83→  /// </summary>
 84→  public event EventHandler<ConnectionState>? ConnectionStateChanged;
 85→
 86→  /// <summary>
 87→  /// Raised when the peer count changes.
 88→  /// </summary>
 89→  public event EventHandler<int>? PeerCountChanged;
 90→
 91→  /// <summary>
 92→  /// Initializes the repo, storage, and network adapter.
 93→  /// Creates the storage directory, connects to the SignalR hub, and starts the repo.
 94→  /// </summary>
 95→  public async Task InitializeAsync()
 96→  {
 97→    ThrowIfDisposed();
 98→
 99→    if(_repo is not null)
100→    {
101→      _logger.LogWarning("RepoService is already initialized");
102→      return;
103→    }
104→
105→    _logger.LogInformation("Initializing RepoService for app '{AppName}'", _options.AppName);
106→
107→    // Create file system storage
108→    string storageDir = StorageDirectory;
109→    Directory.CreateDirectory(storageDir);
110→    _storage = new FileSystemStorageAdapter(storageDir);
111→    _logger.LogInformation("Storage initialized at: {StorageDir}", storageDir);
112→
113→    // Create SignalR connection service
114→    IOptionsMonitor<SignalRConnectionServiceOptions> optionsMonitor =
115→      new StaticOptionsMonitor(new SignalRConnectionServiceOptions
116→      {
117→        HubUrl = _options.HubUrl,
118→        AutoStart = true,
119→        EnableAutomaticReconnect = true,
120→        UseMessagePackProtocol = true
121→      });
122→
123→    _connectionService = new SignalRConnectionService(_loggerFactory, optionsMonitor, string.Empty);
124→
125→    // Create network adapter
126→    _networkAdapter = new SignalRNetworkAdapter(_connectionService, _loggerFactory);
127→
128→    // Create repo
129→    _repo = new Repo(new RepoConfig
130→    {
131→      Storage = _storage,
132→      NetworkAdapters = [_networkAdapter]
133→    });
134→
135→    _logger.LogInformation("Repo created with PeerId: {PeerId}", _repo.PeerId);
136→
137→    // Wire up peer events
138→    _repo.PeerConnected += OnPeerConnected;
139→    _repo.PeerDisconnected += OnPeerDisconnected;
140→
141→    // Connect the network adapter
142→    SetConnectionState(ConnectionState.Connecting);
143→
144→    try
145→    {
146→      _networkAdapter.Connect(_repo.PeerId);
147→      await _networkAdapter.WhenReady().WaitAsync(TimeSpan.FromSeconds(10));
148→      SetConnectionState(ConnectionState.Connected);
149→      _logger.LogInformation("Connected to SignalR hub: {HubUrl}", _options.HubUrl);
150→    }
151→    catch(Exception ex)
152→    {
153→      _logger.LogWarning(ex, "Failed to connect to SignalR hub: {HubUrl}. Repo will work offline.", _options.HubUrl);
154→      SetConnectionState(ConnectionState.Disconnected);
155→    }
156→  }
157→
158→  void OnPeerConnected(object? sender, PeerEventArgs e)
159→  {
160→    int count = Interlocked.Increment(ref _peerCount);
161→    _logger.LogInformation("Peer connected: {PeerId}. Total peers: {PeerCount}", e.PeerId, count);
162→    PeerCountChanged?.Invoke(this, count);
163→  }
164→
165→  void OnPeerDisconnected(object? sender, PeerEventArgs e)
166→  {
167→    int count = Interlocked.Add(ref _peerCount, -1);
168→    if(count < 0)
169→    {
170→      Interlocked.Exchange(ref _peerCount, 0);
171→      count = 0;
172→    }
173→
174→    _logger.LogInformation("Peer disconnected: {PeerId}. Total peers: {PeerCount}", e.PeerId, count);
175→    PeerCountChanged?.Invoke(this, count);
176→  }
177→
178→  void SetConnectionState(ConnectionState state)
179→  {
180→    if(_connectionState == state)
181→    {
182→      return;
183→    }
184→
185→    _connectionState = state;
186→    _logger.LogInformation("Connection state changed to: {State}", state);
187→    ConnectionStateChanged?.Invoke(this, state);
188→  }
189→
190→  /// <inheritdoc />
191→  public void Dispose()
192→  {
193→    if(_disposed)
194→    {
195→      return;
196→    }
197→
198→    _disposed = true;
199→
200→    if(_repo is not null)
201→    {
202→      _repo.PeerConnected -= OnPeerConnected;
203→      _repo.PeerDisconnected -= OnPeerDisconnected;
204→      _repo.Dispose();
205→    }
206→
207→    _networkAdapter?.Dispose();
208→    _connectionService?.Dispose();
209→    _storage?.Dispose();
210→  }
211→
212→  void ThrowIfDisposed()
213→  {
214→    ObjectDisposedException.ThrowIf(_disposed, this);
215→  }
216→
217→  /// <summary>
218→  /// Simple IOptionsMonitor implementation for creating SignalRConnectionService without DI.
219→  /// </summary>
220→  sealed class StaticOptionsMonitor(SignalRConnectionServiceOptions options)
221→    : IOptionsMonitor<SignalRConnectionServiceOptions>
222→  {
223→    public SignalRConnectionServiceOptions CurrentValue => options;
224→
225→    public SignalRConnectionServiceOptions Get(string? name) => options;
226→
227→    public IDisposable? OnChange(Action<SignalRConnectionServiceOptions, string?> listener) => null;
228→  }
229→}
