  3→using System.Collections.ObjectModel;
  4→using System.ComponentModel;
  5→using System.Runtime.CompilerServices;
  6→
  7→namespace DemoApp.Shared.Controls;
  8→
  9→/// <summary>
 10→/// ViewModel for the <see cref="DocumentSessionDialog"/> control.
 11→/// </summary>
 12→[PublicAPI]
 13→public sealed class DocumentSessionDialogViewModel : INotifyPropertyChanged
 14→{
 15→  string _joinDocumentId = string.Empty;
 16→  SessionResult? _result;
 17→
 18→  /// <inheritdoc />
 19→  public event PropertyChangedEventHandler? PropertyChanged;
 20→
 21→  /// <summary>
 22→  /// Raised when the user has made a selection and the dialog should close.
 23→  /// </summary>
 24→  public event EventHandler? ResultReady;
 25→
 26→  /// <summary>
 27→  /// Gets or sets the document ID to join.
 28→  /// </summary>
 29→  public string JoinDocumentId
 30→  {
 31→    get => _joinDocumentId;
 32→    set
 33→    {
 34→      if(_joinDocumentId == value)
 35→      {
 36→        return;
 37→      }
 38→
 39→      _joinDocumentId = value;
 40→      OnPropertyChanged();
 41→      OnPropertyChanged(nameof(CanJoin));
 42→    }
 43→  }
 44→
 45→  /// <summary>
 46→  /// Gets whether the Join button should be enabled.
 47→  /// </summary>
 48→  public bool CanJoin => !string.IsNullOrWhiteSpace(_joinDocumentId);
 49→
 50→  /// <summary>
 51→  /// Gets the list of previously stored document IDs.
 52→  /// </summary>
 53→  public ObservableCollection<string> StoredDocuments { get; } = [];
 54→
 55→  /// <summary>
 56→  /// Gets the dialog result after the user makes a selection.
 57→  /// </summary>
 58→  public SessionResult? Result
 59→  {
 60→    get => _result;
 61→    private set
 62→    {
 63→      _result = value;
 64→      OnPropertyChanged();
 65→    }
 66→  }
 67→
 68→  /// <summary>
 69→  /// Creates a new document.
 70→  /// </summary>
 71→  public void CreateNew()
 72→  {
 73→    Result = new SessionResult { Action = SessionAction.Create };
 74→    ResultReady?.Invoke(this, EventArgs.Empty);
 75→  }
 76→
 77→  /// <summary>
 78→  /// Joins an existing document using the entered document ID.
 79→  /// </summary>
 80→  public void Join()
 81→  {
 82→    if(!CanJoin)
 83→    {
 84→      return;
 85→    }
 86→
 87→    Result = new SessionResult
 88→    {
 89→      Action = SessionAction.Join,
 90→      DocumentId = _joinDocumentId.Trim()
 91→    };
 92→
 93→    ResultReady?.Invoke(this, EventArgs.Empty);
 94→  }
 95→
 96→  /// <summary>
 97→  /// Resumes a previously stored document.
 98→  /// </summary>
 99→  /// <param name="documentId">The stored document ID to resume.</param>
100→  public void Resume(string documentId)
101→  {
102→    Result = new SessionResult
103→    {
104→      Action = SessionAction.Resume,
105→      DocumentId = documentId
106→    };
107→
108→    ResultReady?.Invoke(this, EventArgs.Empty);
109→  }
110→
111→  /// <summary>
112→  /// Scans the storage directory for previously stored documents.
113→  /// Uses the FileSystemStorageAdapter's sharded directory structure.
114→  /// </summary>
115→  /// <param name="storageDirectory">The base storage directory to scan.</param>
116→  public void LoadStoredDocuments(string storageDirectory)
117→  {
118→    StoredDocuments.Clear();
119→
120→    if(!Directory.Exists(storageDirectory))
121→    {
122→      return;
123→    }
124→
125→    // FileSystemStorageAdapter sharding: first 2 chars are the shard dir,
126→    // remaining chars are the subdirectory name.
127→    // Reconstruct document IDs by combining shard prefix + subdirectory name.
128→    foreach(string shardDir in Directory.GetDirectories(storageDirectory))
129→    {
130→      string shardName = Path.GetFileName(shardDir);
131→      if(shardName.Length != 2)
132→      {
133→        continue;
134→      }
135→
136→      foreach(string docDir in Directory.GetDirectories(shardDir))
137→      {
138→        string docSuffix = Path.GetFileName(docDir);
139→        string documentId = shardName + docSuffix;
140→        StoredDocuments.Add(documentId);
141→      }
142→    }
143→  }
144→
145→  void OnPropertyChanged([CallerMemberName] string? propertyName = null)
146→  {
147→    PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(propertyName));
148→  }
149→}
