 10→/// </summary>
 11→[PublicAPI]
 12→public sealed class ConnectionStatusBarViewModel : INotifyPropertyChanged
 13→{
 14→  ConnectionState _connectionState;
 15→  string? _peerId;
 16→  int _peerCount;
 17→  string? _documentId;
 18→  string? _serverUrl;
 19→
 20→  /// <inheritdoc />
