 84→    get => _documentId;
 85→    set
 86→    {
 87→      if(_documentId == value)
 88→      {
 89→        return;
 90→      }
 91→
 92→      _documentId = value;
 93→      OnPropertyChanged();
 94→    }
 95→  }
 96→
 97→  /// <summary>
 98→  /// Gets or sets the server URL.
 99→  /// </summary>
100→  public string? ServerUrl
101→  {
102→    get => _serverUrl;
103→    set
104→    {
105→      if(_serverUrl == value)
106→      {
107→        return;
108→      }
109→
110→      _serverUrl = value;
111→      OnPropertyChanged();
112→    }
113→  }
114→
115→  /// <summary>
116→  /// Gets a truncated version of the peer ID for display.
117→  /// </summary>
118→  public string TruncatedPeerId
119→  {
120→    get
121→    {
122→      if(string.IsNullOrEmpty(_peerId))
123→      {
124→        return "-";
125→      }
126→
127→      return _peerId.Length > 12 ? $"{_peerId[..12]}..." : _peerId;
128→    }
129→  }
130→
131→  /// <summary>
132→  /// Gets a human-readable text for the connection state.
133→  /// </summary>
134→  public string ConnectionStateText => _connectionState switch
135→  {
136→    ConnectionState.Disconnected => "Disconnected",
137→    ConnectionState.Connecting => "Connecting...",
138→    ConnectionState.Connected => "Connected",
139→    ConnectionState.Reconnecting => "Reconnecting...",
140→    _ => "Unknown"
141→  };
142→
143→  void OnPropertyChanged([CallerMemberName] string? propertyName = null)
144→  {
145→    PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(propertyName));
146→  }
147→}
