 13→
 14→public partial class MainWindow : Window
 15→{
 16→  DocumentSessionDialogViewModel? _sessionVm;
 17→  ConnectionStatusBarViewModel? _statusBarVm;
 18→
 19→  public MainWindow()
 20→  {
 21→    InitializeComponent();
 22→    Loaded += OnLoaded;
 23→  }
 24→
 25→  void OnLoaded(object? sender, EventArgs e)
 26→  {
 27→    _sessionVm = new DocumentSessionDialogViewModel();
 28→    _sessionVm.ResultReady += OnSessionResultReady;
 29→
 30→    SessionDialog.DataContext = _sessionVm;
 31→
 32→    _statusBarVm = new ConnectionStatusBarViewModel();
 33→    StatusBar.DataContext = _statusBarVm;
 34→
 35→    // Track caret position changes from the TextBox
 36→    LocalEditor.PropertyChanged += (_, args) =>
 37→    {
 38→      if(args.Property == TextBox.CaretIndexProperty && DataContext is TextEditorViewModel vm)
 39→      {
 40→        vm.CursorPosition = LocalEditor.CaretIndex;
 41→      }
 42→    };
 43→
 44→    // Load stored documents if RepoService is available
 45→    if(DataContext is TextEditorViewModel vm2 && vm2.RepoService is not null)
 46→    {
 47→      _sessionVm.LoadStoredDocuments(vm2.RepoService.StorageDirectory);
 48→    }
 49→  }
 50→
 51→  async void OnSessionResultReady(object? sender, EventArgs e)
 52→  {
 53→    if(_sessionVm?.Result is null || DataContext is not TextEditorViewModel vm)
 54→    {
 55→      return;
 56→    }
 57→
 58→    var result = _sessionVm.Result;
 59→
 60→    try
 61→    {
 62→      switch(result.Action)
 63→      {
 64→        case SessionAction.Create:
 65→          await HandleCreateAsync(vm);
 66→          break;
 67→        case SessionAction.Join:
 68→          await HandleJoinAsync(vm, result.DocumentId!);
 69→          break;
 70→        case SessionAction.Resume:
 71→          await HandleResumeAsync(vm, result.DocumentId!);
 72→          break;
 73→      }
 74→    }
 75→    catch(Exception ex)
 76→    {
 77→      vm.SyncStatus = $"Error: {ex.Message}";
 78→    }
 79→  }
 80→
 81→  async Task HandleCreateAsync(TextEditorViewModel vm)
 82→  {
 83→    if(vm.RepoService is null)
 84→    {
 85→      // Offline mode: create a standalone document
 86→      var automergeService = new AutomergeService();
 87→      vm.SetAutomergeService(automergeService);
 88→      ShowEditor(null);
 89→      return;
 90→    }
 91→
 92→    await vm.RepoService.InitializeAsync();
 93→    WireConnectionEvents(vm.RepoService);
 94→
 95→    // Create a new document via the repo
 96→    var handle = vm.RepoService.Repo!.Create<object>();
 97→    await handle.WhenReadyAsync();
 98→
 99→    // Initialize text CRDT on the document
100→    handle.Change(doc =>
101→    {
102→      doc.PutObject(doc.RootId, "content", AutomergeContainerType.Text);
103→    }, "Initialize text field");
104→
105→    var document = ((IDocHandle)handle).GetDocument()!;
106→    var automerge = AutomergeService.FromDocument(document);
107→    vm.SetAutomergeService(automerge);
108→    vm.DocHandle = handle;
109→
110→    ShowEditor(handle.DocumentId.ToString());
111→  }
112→
113→  async Task HandleJoinAsync(TextEditorViewModel vm, string documentId)
114→  {
115→    if(vm.RepoService is null)
116→    {
117→      vm.SyncStatus = "Cannot join: no server connection";
118→      return;
119→    }
120→
121→    await vm.RepoService.InitializeAsync();
122→    WireConnectionEvents(vm.RepoService);
123→
124→    vm.SyncStatus = "Joining document...";
125→
126→    var handle = await vm.RepoService.Repo!.Find<object>(documentId, TimeSpan.FromSeconds(30));
127→    if(handle is null)
128→    {
129→      vm.SyncStatus = "Document not found";
130→      return;
131→    }
132→
133→    await handle.WhenReadyAsync();
134→
135→    var document = ((IDocHandle)handle).GetDocument()!;
136→    var automerge = AutomergeService.FromDocument(document);
137→    vm.SetAutomergeService(automerge);
138→    vm.DocHandle = handle;
139→
140→    ShowEditor(handle.DocumentId.ToString());
141→  }
142→
143→  async Task HandleResumeAsync(TextEditorViewModel vm, string documentId)
144→  {
145→    if(vm.RepoService is null)
146→    {
147→      vm.SyncStatus = "Cannot resume: no server connection";
148→      return;
149→    }
150→
151→    await vm.RepoService.InitializeAsync();
152→    WireConnectionEvents(vm.RepoService);
153→
154→    vm.SyncStatus = "Resuming document...";
155→
156→    // Find will load from local storage first
157→    var handle = await vm.RepoService.Repo!.Find<object>(documentId, TimeSpan.FromSeconds(10));
158→    if(handle is null)
159→    {
160→      vm.SyncStatus = "Document not found in storage";
161→      return;
162→    }
163→
164→    await handle.WhenReadyAsync();
165→
166→    var document = ((IDocHandle)handle).GetDocument()!;
167→    var automerge = AutomergeService.FromDocument(document);
168→    vm.SetAutomergeService(automerge);
169→    vm.DocHandle = handle;
170→
171→    ShowEditor(handle.DocumentId.ToString());
172→  }
173→
174→  void WireConnectionEvents(RepoService repoService)
175→  {
176→    if(_statusBarVm is null)
177→    {
178→      return;
179→    }
180→
181→    _statusBarVm.PeerId = repoService.PeerId?.ToString();
182→    _statusBarVm.ServerUrl = repoService is { IsInitialized: true }
183→      ? "Connected"
184→      : "Offline";
185→
186→    repoService.ConnectionStateChanged += (_, state) =>
187→      Dispatcher.UIThread.Post(() =>
188→      {
189→        if(_statusBarVm is null)
190→        {
191→          return;
192→        }
193→
194→        _statusBarVm.ConnectionState = state switch
195→        {
196→          ConnectionState.Connected => DemoApp.Shared.ConnectionState.Connected,
197→          ConnectionState.Connecting => DemoApp.Shared.ConnectionState.Connecting,
198→          ConnectionState.Reconnecting => DemoApp.Shared.ConnectionState.Reconnecting,
199→          _ => DemoApp.Shared.ConnectionState.Disconnected
200→        };
201→      });
202→
203→    repoService.PeerCountChanged += (_, count) =>
204→      Dispatcher.UIThread.Post(() =>
205→      {
206→        if(_statusBarVm is not null)
207→        {
208→          _statusBarVm.PeerCount = count;
209→        }
210→      });
211→  }
212→
213→  void ShowEditor(string? documentId)
214→  {
215→    Dispatcher.UIThread.Post(() =>
216→    {
217→      SessionPanel.IsVisible = false;
218→      EditorPanel.IsVisible = true;
219→
220→      if(_statusBarVm is not null)
221→      {
222→        _statusBarVm.DocumentId = documentId ?? "local";
223→      }
224→
225→      LocalEditor.Focus();
226→    });
227→  }
228→}
