 12→namespace DemoApp.CollaborativeTextEditor.ViewModels;
 13→
 14→public class TextEditorViewModel : ViewModelBase, IDisposable
 15→{
 16→  readonly RepoService? _repoService;
 17→  readonly ILogger<TextEditorViewModel> _logger;
 18→  readonly Action<Action> _dispatcher;
 19→  AutomergeService? _automergeService;
 20→  DocHandle<object>? _docHandle;
 21→  AutomergeCursor? _savedCursor;
 22→  string _documentText = string.Empty;
 23→  string _syncStatus = "Disconnected";
 24→  int _cursorPosition;
 25→  bool _isRemoteUpdate;
 26→  bool _disposed;
 27→
 28→  public TextEditorViewModel(
 29→    RepoService? repoService = null,
 30→    ILoggerFactory? loggerFactory = null,
 31→    Action<Action>? dispatcher = null)
 32→  {
 33→    _repoService = repoService;
 34→    _logger = (loggerFactory ?? NullLoggerFactory.Instance).CreateLogger<TextEditorViewModel>();
 35→    _dispatcher = dispatcher ?? (action => action());
 36→
 37→    SaveCommand = ReactiveCommand.Create(SaveDocument);
 38→    ExportJsonCommand = ReactiveCommand.Create(ExportJson);
 39→  }
 40→
 41→  /// <summary>
 42→  /// The current text content of the local Automerge document.
 43→  /// Two-way bound to the TextBox in the view.
 44→  /// </summary>
 45→  public string DocumentText
 46→  {
 47→    get => _documentText;
 48→    set
 49→    {
 50→      if(_documentText == value)
 51→      {
 52→        return;
 53→      }
 54→
 55→      if(_automergeService is not null && !_isRemoteUpdate)
 56→      {
 57→        ApplyTextChange(value);
 58→      }
 59→
 60→      this.RaiseAndSetIfChanged(ref _documentText, value);
 61→    }
 62→  }
 63→
 64→  /// <summary>
 65→  /// Current sync status description.
 66→  /// </summary>
 67→  public string SyncStatus
 68→  {
 69→    get => _syncStatus;
 70→    set => this.RaiseAndSetIfChanged(ref _syncStatus, value);
 71→  }
 72→
 73→  /// <summary>
 74→  /// Current cursor position in the local document.
 75→  /// </summary>
 76→  public int CursorPosition
 77→  {
 78→    get => _cursorPosition;
 79→    set => this.RaiseAndSetIfChanged(ref _cursorPosition, value);
 80→  }
 81→
 82→  /// <summary>
 83→  /// Gets the RepoService for document operations.
 84→  /// </summary>
 85→  internal RepoService? RepoService => _repoService;
 86→
 87→  /// <summary>
 88→  /// Gets the AutomergeService for text CRDT operations.
 89→  /// </summary>
 90→  internal AutomergeService? AutomergeService => _automergeService;
 91→
 92→  /// <summary>
 93→  /// Gets or sets the DocHandle for collaborative sync. Set by MainWindow after document creation/join.
 94→  /// </summary>
 95→  internal DocHandle<object>? DocHandle
 96→  {
 97→    get => _docHandle;
 98→    set
 99→    {
100→      if(_docHandle is not null)
101→      {
102→        _docHandle.Changed -= OnDocHandleChanged;
103→      }
104→
105→      _docHandle = value;
106→
107→      if(_docHandle is not null)
108→      {
109→        _docHandle.Changed += OnDocHandleChanged;
110→      }
111→    }
112→  }
113→
114→  public ReactiveCommand<Unit, Unit> SaveCommand { get; }
115→
116→  public ReactiveCommand<Unit, Unit> ExportJsonCommand { get; }
117→
118→  /// <summary>
119→  /// Sets the AutomergeService for text operations (after document is created/loaded).
120→  /// </summary>
121→  internal void SetAutomergeService(AutomergeService service)
122→  {
123→    _automergeService = service;
124→    RefreshFromDocument();
125→  }
126→
127→  internal void ApplyTextChange(string newText)
128→  {
129→    if(_automergeService is null)
130→    {
131→      return;
132→    }
133→
134→    string currentText = _automergeService.GetText();
135→
136→    // Find the difference and apply as a splice operation.
137→    // This is a simplified diff: find common prefix and suffix.
138→    int prefixLen = 0;
139→    int minLen = Math.Min(currentText.Length, newText.Length);
140→    while(prefixLen < minLen && currentText[prefixLen] == newText[prefixLen])
141→    {
142→      prefixLen++;
143→    }
144→
145→    int suffixLen = 0;
146→    int maxSuffix = minLen - prefixLen;
147→    while(suffixLen < maxSuffix
148→      && currentText[currentText.Length - 1 - suffixLen] == newText[newText.Length - 1 - suffixLen])
149→    {
150→      suffixLen++;
151→    }
152→
153→    int deleteCount = currentText.Length - prefixLen - suffixLen;
154→    string insertText = newText.Substring(prefixLen, newText.Length - prefixLen - suffixLen);
155→
156→    if(deleteCount > 0 || insertText.Length > 0)
157→    {
158→      // Save cursor position before edit for later restoration
159→      SaveCursorBeforeEdit();
160→      _automergeService.SpliceText((ulong)prefixLen, deleteCount, insertText);
161→    }
162→  }
163→
164→  internal void RefreshFromDocument()
165→  {
166→    if(_automergeService is null)
167→    {
168→      return;
169→    }
170→
171→    string text = _automergeService.GetText();
172→    if(_documentText != text)
173→    {
174→      _isRemoteUpdate = true;
175→      try
176→      {
177→        _documentText = text;
178→        this.RaisePropertyChanged(nameof(DocumentText));
179→      }
180→      finally
181→      {
182→        _isRemoteUpdate = false;
183→      }
184→    }
185→  }
186→
187→  void OnDocHandleChanged(object? sender, DocHandleChangeEventArgs<object> e)
188→  {
189→    if(e.IsLocal)
190→    {
191→      return;
192→    }
193→
194→    _dispatcher(() =>
195→    {
196→      SaveCursorBeforeEdit();
197→      RefreshFromDocument();
198→      RestoreCursorAfterEdit();
199→    });
200→  }
201→
202→  void SaveCursorBeforeEdit()
203→  {
204→    if(_automergeService is null || _cursorPosition <= 0)
205→    {
206→      _savedCursor = null;
207→      return;
208→    }
209→
210→    try
211→    {
212→      ulong pos = (ulong)Math.Min(_cursorPosition, _automergeService.GetText().Length);
213→      if(pos > 0)
214→      {
215→        _savedCursor = _automergeService.GetCursor(pos - 1);
216→      }
217→      else
218→      {
219→        _savedCursor = null;
220→      }
221→    }
222→    catch(Exception)
223→    {
224→      _savedCursor = null;
225→    }
226→  }
227→
228→  void RestoreCursorAfterEdit()
229→  {
230→    if(_automergeService is null || _savedCursor is null)
231→    {
232→      return;
233→    }
234→
235→    try
236→    {
237→      ulong pos = _automergeService.GetCursorPosition(_savedCursor);
238→      CursorPosition = (int)(pos + 1);
239→    }
240→    catch(Exception)
241→    {
242→      // Cursor may be invalid after merge — leave at current position
243→    }
244→
245→    _savedCursor = null;
246→  }
247→
248→  void SaveDocument()
249→  {
250→    if(_automergeService is null)
251→    {
252→      SyncStatus = "No document loaded";
253→      return;
254→    }
255→
256→    byte[] saved = _automergeService.Save();
257→    SyncStatus = $"Saved ({saved.Length} bytes)";
258→  }
259→
260→  void ExportJson()
261→  {
262→    if(_automergeService is null)
263→    {
264→      SyncStatus = "No document loaded";
265→      return;
266→    }
267→
268→    string json = _automergeService.Document.HydrateJson();
269→    _logger.LogInformation("Document JSON: {Json}", json);
270→    SyncStatus = $"Exported JSON ({json.Length} chars)";
271→  }
272→
273→  public void Dispose()
274→  {
275→    if(!_disposed)
276→    {
277→      _disposed = true;
278→
279→      if(_docHandle is not null)
280→      {
281→        _docHandle.Changed -= OnDocHandleChanged;
282→      }
283→
284→      _automergeService?.Dispose();
285→      _repoService?.Dispose();
286→    }
287→  }
288→}
