  4→namespace Ray.Automerge.Repo.Network.SignalR;
  5→
  6→/// <summary>
  7→/// SignalR-based network adapter for Automerge document synchronization.
  8→/// </summary>
  9→/// <remarks>
 10→/// This adapter provides real-time collaborative editing over ASP.NET Core SignalR with:
 11→/// <list type="bullet">
 12→///   <item><description>Automatic reconnection and connection lifecycle management</description></item>
 13→///   <item><description>MessagePack serialization with LZ4 compression for bandwidth efficiency</description></item>
 14→///   <item><description>Document-based group subscriptions for targeted message delivery</description></item>
 15→///   <item><description>Thread-safe operations with concurrent access support</description></item>
 16→/// </list>
 17→///
 18→/// <para>
 19→/// <strong>Usage Example:</strong>
 20→/// <code>
 21→/// var adapter = new SignalRNetworkAdapter(connectionService, loggerFactory);
 22→/// adapter.MessageReceived += (sender, args) => {
 23→///   Console.WriteLine($"Received: {args.Message.MessageType}");
 24→/// };
 25→/// adapter.Connect(PeerId.Generate(), null);
 26→/// await adapter.WhenReady();
 27→/// adapter.Send(syncMessage);
 28→/// </code>
 29→/// </para>
 30→/// </remarks>
 31→[PublicAPI]
 32→public sealed class SignalRNetworkAdapter : INetworkAdapter, IDocumentsHubClient, IDisposable, IAsyncDisposable
 33→{
 34→  readonly ISignalRConnectionService _connectionService;
 35→  readonly ILogger<SignalRNetworkAdapter> _logger;
 36→  readonly string _adapterId;
 37→  readonly SemaphoreSlim _lock = new(1, 1);
 38→  readonly TaskCompletionSource _readyTcs = new();
 39→  readonly ConcurrentDictionary<string, byte> _subscribedDocuments = new();
 40→
 41→  HubConnection? _connection;
 42→  PeerId? _peerId;
 43→  bool _isReady;
 44→  bool _disposed;
 45→
 46→  /// <summary>
 47→  /// Initializes a new instance of the <see cref="SignalRNetworkAdapter"/> class.
 48→  /// </summary>
 49→  /// <param name="connectionService">The SignalR connection service.</param>
 50→  /// <param name="loggerFactory">The logger factory.</param>
 51→  public SignalRNetworkAdapter(
 52→    ISignalRConnectionService connectionService,
 53→    ILoggerFactory loggerFactory)
 54→  {
 55→    _connectionService = connectionService ?? throw new ArgumentNullException(nameof(connectionService));
 56→    ArgumentNullException.ThrowIfNull(loggerFactory);
 57→
 58→    _logger = loggerFactory.CreateLogger<SignalRNetworkAdapter>();
 59→    _adapterId = $"signalr-{Guid.NewGuid():N}";
 60→  }
 61→
 62→  /// <inheritdoc />
 63→  public string AdapterId => _adapterId;
 64→
 65→  /// <inheritdoc />
 66→  public bool IsReady => _isReady;
 67→
 68→  /// <inheritdoc />
 69→  public Task WhenReady() => _readyTcs.Task;
 70→
 71→  /// <inheritdoc />
 72→  public event EventHandler<PeerCandidateEventArgs>? PeerCandidate;
 73→
 74→  /// <inheritdoc />
 75→  public event EventHandler<PeerDisconnectedEventArgs>? PeerDisconnected;
 76→
 77→  /// <inheritdoc />
 78→  public event EventHandler<MessageReceivedEventArgs>? MessageReceived;
 79→
 80→  /// <inheritdoc />
 81→  public event EventHandler? Closed;
 82→
 83→  /// <inheritdoc />
 84→  public void Connect(PeerId peerId, PeerMetadata? metadata = null)
 85→  {
 86→    if (_disposed)
 87→      throw new ObjectDisposedException(nameof(SignalRNetworkAdapter));
 88→
 89→    _ = ConnectAsyncInternal(peerId, metadata);
 90→  }
 91→
 92→  async Task ConnectAsyncInternal(PeerId peerId, PeerMetadata? metadata)
 93→  {
 94→    await _lock.WaitAsync();
 95→    try
 96→    {
 97→      if (_isReady)
 98→      {
 99→        _logger.LogWarning("Adapter already connected. Ignoring duplicate Connect call.");
100→        return;
101→      }
102→
103→      _logger.LogInformation("Connecting SignalR adapter for peer: {PeerId}", peerId);
104→      _peerId = peerId;
105→
106→      // Get connection from service
107→      _connection = await _connectionService.GetConnection();
108→      _logger.LogDebug("SignalR connection established. ConnectionId={ConnectionId}", _connection.ConnectionId ?? "<pending>");
109→
110→      // Register client methods for hub callbacks
111→      _logger.LogDebug("Registering hub callbacks for connection {ConnectionId}", _connection.ConnectionId ?? "<pending>");
112→      _connection.On<MessageDto>(
113→        "OnReceiveMessage",
114→        msg =>
115→        {
116→          _logger.LogTrace("Hub invoked OnReceiveMessage. DocumentId={DocumentId}, MessageType={MessageType}, SenderId={SenderId}",
117→            msg.DocumentId,
118→            msg.MessageType,
119→            msg.SenderId);
120→          _ = ((IDocumentsHubClient)this).OnReceiveMessage(msg);
121→        });
122→      _connection.On<PeerHandshakeDto>(
123→        "OnPeerJoined",
124→        handshake =>
125→        {
126→          _logger.LogTrace("Hub invoked OnPeerJoined for PeerId={PeerId}", handshake.PeerId);
127→          _ = ((IDocumentsHubClient)this).OnPeerJoined(handshake);
128→        });
129→      _connection.On<string>(
130→        "OnPeerLeft",
131→        peerId =>
132→        {
133→          _logger.LogTrace("Hub invoked OnPeerLeft for PeerId={PeerId}", peerId);
134→          _ = ((IDocumentsHubClient)this).OnPeerLeft(peerId);
135→        });
136→
137→      // Hook connection lifecycle events
138→      _connection.Closed += OnConnectionClosedAsync;
139→
140→      // Send handshake
141→      var handshake = PeerHandshakeDto.Create(peerId, metadata);
142→      await _connection.InvokeAsync("Handshake", handshake);
143→
144→      _logger.LogInformation("Handshake completed for peer: {PeerId}", peerId);
145→
146→      // Mark ready
147→      _isReady = true;
148→      _readyTcs.TrySetResult();
149→
150→      // Raise PeerCandidate event (we're connected to the server)
151→      RaisePeerCandidate(peerId, metadata);
152→    }
153→    catch (Exception ex)
154→    {
155→      _logger.LogError(ex, "Failed to connect SignalR adapter for peer: {PeerId}", peerId);
156→      _readyTcs.TrySetException(ex);
157→      throw;
158→    }
159→    finally
160→    {
161→      _lock.Release();
162→    }
163→  }
164→
165→  /// <inheritdoc />
166→  public void Send(IRepoMessage message)
167→  {
168→    if (_disposed)
169→      throw new ObjectDisposedException(nameof(SignalRNetworkAdapter));
170→
171→    ArgumentNullException.ThrowIfNull(message);
172→
173→    _ = SendAsyncInternal(message);
174→  }
175→
176→  async Task SendAsyncInternal(IRepoMessage message)
177→  {
178→    await _lock.WaitAsync();
179→    try
180→    {
181→      if (!_isReady || _connection is null)
182→      {
183→        _logger.LogWarning("Cannot send message: adapter not ready or connection is null");
184→        return;
185→      }
186→
187→      var documentId = message.DocumentId;
188→
189→      if (documentId is null)
190→      {
191→        _logger.LogWarning("Cannot send message: DocumentId is null or empty");
192→        return;
193→      }
194→
195→      if (_peerId is null)
196→      {
197→        _logger.LogWarning("Cannot send message type {MessageType}: adapter has no peer ID assigned", message.MessageType);
198→        return;
199→      }
200→
201→      // Auto-subscribe to document if not already subscribed
202→      var documentIdValue = documentId.Value;
203→      var documentIdString = documentIdValue.Value;
204→
205→      if (!_subscribedDocuments.ContainsKey(documentIdString))
206→      {
207→        _logger.LogDebug("Auto-subscribing to document: {DocumentId}", documentIdString);
208→        await SubscribeToDocumentInternalAsync(documentIdString);
209→      }
210→
211→      var messageWithSender = EnsureSender(message, _peerId.Value);
212→
213→      if (messageWithSender.SenderId is null && messageWithSender is DocumentSnapshotMessage snapshotWithoutSender)
214→      {
215→        messageWithSender = snapshotWithoutSender with { SenderId = _peerId.Value };
216→      }
217→
218→      _logger.LogInformation(
219→        "Sending {MessageType} message for document {DocumentId} via SignalR connection {ConnectionId} as sender {SenderId}",
220→        messageWithSender.MessageType,
221→        messageWithSender.DocumentId?.Value,
222→        _connection.ConnectionId ?? "<pending>",
223→        messageWithSender.SenderId?.ToString());
224→
225→      // Create MessageDto
226→      var messageData = GetMessageData(messageWithSender);
227→      var messageDto = MessageDto.FromRepoMessage(messageWithSender, messageData!);
228→
229→      // Send to hub
230→      await _connection.InvokeAsync("SendMessage", messageDto);
231→
232→      _logger.LogInformation("Hub accepted {MessageType} message for document {DocumentId} on connection {ConnectionId}",
233→        messageWithSender.MessageType,
234→        messageWithSender.DocumentId?.Value,
235→        _connection.ConnectionId ?? "<pending>");
236→    }
237→    catch (Exception ex)
238→    {
239→      _logger.LogError(ex, "Failed to send message type {MessageType} for document {DocumentId}",
240→        message.MessageType, message.DocumentId?.Value);
241→    }
242→    finally
243→    {
244→      _lock.Release();
245→    }
246→  }
247→
248→  /// <summary>
249→  /// Subscribes to a document to receive sync messages.
250→  /// </summary>
251→  /// <param name="documentId">The document ID to subscribe to.</param>
252→  public async Task SubscribeToDocumentAsync(string documentId)
253→  {
254→    if (_disposed)
255→      throw new ObjectDisposedException(nameof(SignalRNetworkAdapter));
256→
257→    ArgumentException.ThrowIfNullOrEmpty(documentId);
258→
259→    await _lock.WaitAsync();
260→    try
261→    {
262→      await SubscribeToDocumentInternalAsync(documentId);
263→    }
264→    finally
265→    {
266→      _lock.Release();
267→    }
268→  }
269→
270→  async Task SubscribeToDocumentInternalAsync(string documentId)
271→  {
272→    if (_subscribedDocuments.ContainsKey(documentId))
273→    {
274→      _logger.LogDebug("Already subscribed to document: {DocumentId}", documentId);
275→      return;
276→    }
277→
278→    if (_connection is null)
279→    {
280→      _logger.LogWarning("Cannot subscribe: connection is null");
281→      return;
282→    }
283→
284→    await _connection.InvokeAsync("SubscribeToDocument", documentId);
285→    _subscribedDocuments.TryAdd(documentId, 0);
286→
287→    _logger.LogInformation("Subscribed to document: {DocumentId}", documentId);
288→  }
289→
290→  /// <summary>
291→  /// Unsubscribes from a document.
292→  /// </summary>
293→  /// <param name="documentId">The document ID to unsubscribe from.</param>
294→  public async Task UnsubscribeFromDocumentAsync(string documentId)
295→  {
296→    if (_disposed)
297→      throw new ObjectDisposedException(nameof(SignalRNetworkAdapter));
298→
299→    ArgumentException.ThrowIfNullOrEmpty(documentId);
300→
301→    await _lock.WaitAsync();
302→    try
303→    {
304→      await UnsubscribeFromDocumentInternalAsync(documentId);
305→    }
306→    finally
307→    {
308→      _lock.Release();
309→    }
310→  }
311→
312→  async Task UnsubscribeFromDocumentInternalAsync(string documentId)
313→  {
314→    if (!_subscribedDocuments.ContainsKey(documentId))
315→    {
316→      _logger.LogDebug("Not subscribed to document: {DocumentId}", documentId);
317→      return;
318→    }
319→
320→    if (_connection is null)
321→    {
322→      _logger.LogWarning("Cannot unsubscribe: connection is null");
323→      return;
324→    }
325→
326→    await _connection.InvokeAsync("UnsubscribeFromDocument", documentId);
327→    _subscribedDocuments.TryRemove(documentId, out _);
328→
329→    _logger.LogInformation("Unsubscribed from document: {DocumentId}", documentId);
330→  }
331→
332→  /// <inheritdoc />
333→  public async Task Disconnect()
334→  {
335→    if (_disposed)
336→      return;
337→
338→    await _lock.WaitAsync();
339→    try
340→    {
341→      if (!_isReady)
342→        return;
343→
344→      _logger.LogInformation("Disconnecting SignalR adapter for peer: {PeerId}", _peerId);
345→
346→      // Unsubscribe from all documents
347→      var documents = _subscribedDocuments.Keys.ToArray();
348→      foreach (var documentId in documents)
349→      {
350→        await UnsubscribeFromDocumentInternalAsync(documentId);
351→      }
352→
353→      // Stop connection
354→      await _connectionService.Stop();
355→
356→      // Clean up
357→      if (_connection is not null)
358→      {
359→        _connection.Closed -= OnConnectionClosedAsync;
360→        _connection = null;
361→      }
362→
363→      _isReady = false;
364→
365→      // Raise events
366→      if (_peerId is not null)
367→        RaisePeerDisconnected(_peerId.Value);
368→
369→      RaiseClosed();
370→
371→      _logger.LogInformation("Disconnected SignalR adapter for peer: {PeerId}", _peerId);
372→    }
373→    finally
374→    {
375→      _lock.Release();
376→    }
377→  }
