379→  /// <inheritdoc />
380→  Task IDocumentsHubClient.OnReceiveMessage(MessageDto messageDto)
381→  {
382→    try
383→    {
384→      _logger.LogInformation("SignalR hub delivered message type {MessageType} for document {DocumentId} from {SenderId}",
385→        messageDto.MessageType, messageDto.DocumentId, messageDto.SenderId);
386→
387→      // Deserialize to IRepoMessage based on MessageType
388→      var message = DeserializeMessage(messageDto);
389→      if (message is null)
390→      {
391→        _logger.LogWarning("Failed to deserialize message type {MessageType}", messageDto.MessageType);
392→        return Task.CompletedTask;
393→      }
394→
395→      // Raise MessageReceived event (deferred to avoid blocking SignalR thread)
396→      _ = Task.Run(() => RaiseMessageReceived(message));
397→    }
398→    catch (Exception ex)
399→    {
400→      _logger.LogError(ex, "Error processing received message type {MessageType}", messageDto.MessageType);
401→    }
402→
403→    return Task.CompletedTask;
404→  }
405→
406→  /// <inheritdoc />
407→  Task IDocumentsHubClient.OnPeerJoined(PeerHandshakeDto handshake)
408→  {
409→    try
410→    {
411→      _logger.LogInformation("Peer joined: PeerId={PeerId}, IsEphemeral={IsEphemeral}",
412→        handshake.PeerId, handshake.Metadata?.IsEphemeral ?? false);
413→
414→      // Raise PeerCandidate event to notify Repo about the new peer
415→      // This will trigger document synchronization with the new peer
416→      var peerId = new PeerId(handshake.PeerId);
417→      var metadata = handshake.Metadata?.ToPeerMetadata();
418→      _ = Task.Run(() => RaisePeerCandidate(peerId, metadata));
419→    }
420→    catch (Exception ex)
421→    {
422→      _logger.LogError(ex, "Error processing peer joined notification for {PeerId}", handshake.PeerId);
423→    }
424→
425→    return Task.CompletedTask;
426→  }
427→
428→  /// <inheritdoc />
429→  Task IDocumentsHubClient.OnPeerLeft(string peerId)
430→  {
431→    try
432→    {
433→      _logger.LogInformation("Peer left: PeerId={PeerId}", peerId);
434→
435→      // Raise PeerDisconnected event to notify Repo
436→      // This will clean up synchronization state for the disconnected peer
437→      var peer = new PeerId(peerId);
438→      _ = Task.Run(() => RaisePeerDisconnected(peer));
439→    }
440→    catch (Exception ex)
441→    {
442→      _logger.LogError(ex, "Error processing peer left notification for {PeerId}", peerId);
443→    }
444→
445→    return Task.CompletedTask;
446→  }
447→
448→  IRepoMessage? DeserializeMessage(MessageDto messageDto)
449→  {
450→    var senderId = new PeerId(messageDto.SenderId);
451→
452→    DocumentId RequireDocumentId(string? value)
453→    {
454→      if(string.IsNullOrWhiteSpace(value))
455→      {
456→        _logger.LogWarning("Received {MessageType} message without a document ID", messageDto.MessageType);
457→        throw new InvalidOperationException($"Message type {messageDto.MessageType} missing document ID");
458→      }
459→
460→      return DocumentId.Parse(value);
461→    }
462→
463→    return messageDto.MessageType switch
464→    {
465→      "sync" => new SyncMessage
466→      {
467→        DocumentId = RequireDocumentId(messageDto.DocumentId),
468→        Data = messageDto.Data,
469→        SenderId = senderId
470→      },
471→      "request" => new RequestMessage
472→      {
473→        DocumentId = RequireDocumentId(messageDto.DocumentId),
474→        Data = messageDto.Data,
475→        SenderId = senderId
476→      },
477→      // Note: Ephemeral messages require additional fields (Count, SessionId) that aren't in MessageDto
478→      // These would need to be encoded in the Data field and deserialized here
479→      // For now, we log a warning and skip these messages
480→      "ephemeral" => LogUnsupportedMessage("ephemeral"),
481→      "doc-unavailable" => new DocumentUnavailableMessage
482→      {
483→        DocumentId = RequireDocumentId(messageDto.DocumentId),
484→        SenderId = senderId
485→      },
486→      "doc-snapshot" => new DocumentSnapshotMessage
487→      {
488→        DocumentId = RequireDocumentId(messageDto.DocumentId),
489→        Data = messageDto.Data ?? Array.Empty<byte>(),
490→        SenderId = senderId
491→      },
492→      // Note: RemoteHeadsChangedMessage requires NewHeads which isn't in MessageDto
493→      "remote-heads-changed" => LogUnsupportedMessage("remote-heads-changed"),
494→      // Note: RemoteSubscriptionChangeMessage has readonly DocumentId
495→      "remote-subscription-change" => LogUnsupportedMessage("remote-subscription-change"),
496→      _ => null
497→    };
498→  }
499→
500→  IRepoMessage? LogUnsupportedMessage(string messageType)
501→  {
502→    _logger.LogWarning("Message type {MessageType} is not yet fully supported in wire protocol", messageType);
503→    return null;
504→  }
505→
506→  Task OnConnectionClosedAsync(Exception? exception)
507→  {
508→    _logger.LogWarning(exception, "SignalR connection closed");
509→
510→    _isReady = false;
511→
512→    if (_peerId is not null)
513→      RaisePeerDisconnected(_peerId.Value);
514→
515→    RaiseClosed();
516→
517→    return Task.CompletedTask;
518→  }
519→
520→  void RaisePeerCandidate(PeerId peerId, PeerMetadata? metadata)
521→  {
522→    try
523→    {
524→      PeerCandidate?.Invoke(this, new PeerCandidateEventArgs
525→      {
526→        PeerId = peerId,
527→        Metadata = metadata
528→      });
529→    }
530→    catch (Exception ex)
531→    {
532→      _logger.LogError(ex, "Error raising PeerCandidate event");
533→    }
534→  }
535→
536→  void RaisePeerDisconnected(PeerId peerId)
537→  {
538→    try
539→    {
540→      PeerDisconnected?.Invoke(this, new PeerDisconnectedEventArgs
541→      {
542→        PeerId = peerId
543→      });
544→    }
545→    catch (Exception ex)
546→    {
547→      _logger.LogError(ex, "Error raising PeerDisconnected event");
548→    }
549→  }
550→
551→  void RaiseMessageReceived(IRepoMessage message)
552→  {
553→    try
554→    {
555→      MessageReceived?.Invoke(this, new MessageReceivedEventArgs
556→      {
557→        Message = message
558→      });
559→    }
560→    catch (Exception ex)
561→    {
562→      _logger.LogError(ex, "Error raising MessageReceived event");
563→    }
564→  }
565→
566→  static byte[]? GetMessageData(IRepoMessage message)
567→  {
568→    return message switch
569→    {
570→      SyncMessage sync => sync.Data,
571→      RequestMessage request => request.Data,
572→      EphemeralMessage ephemeral => ephemeral.Data,
573→      DocumentUnavailableMessage _ => Array.Empty<byte>(),
574→      DocumentSnapshotMessage snapshot => snapshot.Data,
575→      _ => null
576→    };
577→  }
578→
579→  static IRepoMessage EnsureSender(IRepoMessage message, PeerId senderId)
580→  {
581→    if (message.SenderId is not null)
582→      return message;
583→
584→    return message switch
585→    {
586→      SyncMessage sync => sync with { SenderId = senderId },
587→      RequestMessage request => request with { SenderId = senderId },
588→      EphemeralMessage ephemeral => ephemeral with { SenderId = senderId },
589→      DocumentUnavailableMessage unavailable => unavailable with { SenderId = senderId },
590→      RemoteHeadsChangedMessage heads => heads with { SenderId = senderId },
591→      RemoteSubscriptionChangeMessage subscription => subscription with { SenderId = senderId },
592→      _ => message
593→    };
594→  }
595→
596→  void RaiseClosed()
597→  {
598→    try
599→    {
600→      Closed?.Invoke(this, EventArgs.Empty);
601→    }
602→    catch (Exception ex)
603→    {
604→      _logger.LogError(ex, "Error raising Closed event");
605→    }
606→  }
607→
608→  /// <inheritdoc />
609→  public void Dispose()
610→  {
611→    DisposeAsync().AsTask().GetAwaiter().GetResult();
612→  }
613→
614→  /// <inheritdoc />
615→  public async ValueTask DisposeAsync()
616→  {
617→    if (_disposed)
618→      return;
619→
620→    _disposed = true;
621→
622→    await Disconnect();
623→    _lock.Dispose();
624→  }
625→}
