 14→public partial class EditorWindow : Window
 15→{
 16→  DocumentSessionDialogViewModel? _sessionVm;
 17→  ConnectionStatusBarViewModel? _statusBarVm;
 18→
 19→  public EditorWindow()
 20→  {
 21→    InitializeComponent();
 22→    Loaded += OnLoaded;
 23→  }
 24→
 25→  void OnLoaded(object? sender, EventArgs e)
 26→  {
 27→    _sessionVm = new DocumentSessionDialogViewModel();
 28→    _sessionVm.ResultReady += OnSessionResultReady;
 29→
 30→    SessionDialog.DataContext = _sessionVm;
 31→
 32→    _statusBarVm = new ConnectionStatusBarViewModel();
 33→    StatusBar.DataContext = _statusBarVm;
 34→
 35→    // Track caret position and selection changes from the TextBox
 36→    LocalEditor.PropertyChanged += (_, args) =>
 37→    {
 38→      if(DataContext is not EditorViewModel vm)
 39→      {
 40→        return;
 41→      }
 42→
 43→      if(args.Property == TextBox.CaretIndexProperty)
 44→      {
 45→        vm.CursorPosition = LocalEditor.CaretIndex;
 46→      }
 47→
 48→      if(args.Property == TextBox.SelectionStartProperty || args.Property == TextBox.SelectionEndProperty)
 49→      {
 50→        int start = LocalEditor.SelectionStart;
 51→        int end = LocalEditor.SelectionEnd;
 52→        vm.SelectionLength = Math.Abs(end - start);
 53→      }
 54→    };
 55→
 56→    // Load stored documents if RepoService is available
 57→    if(DataContext is EditorViewModel vm2 && vm2.RepoService is not null)
 58→    {
 59→      _sessionVm.LoadStoredDocuments(vm2.RepoService.StorageDirectory);
 60→    }
 61→  }
 62→
 63→  async void OnSessionResultReady(object? sender, EventArgs e)
 64→  {
 65→    if(_sessionVm?.Result is null || DataContext is not EditorViewModel vm)
 66→    {
 67→      return;
 68→    }
 69→
 70→    var result = _sessionVm.Result;
 71→
 72→    try
 73→    {
 74→      switch(result.Action)
 75→      {
 76→        case SessionAction.Create:
 77→          await HandleCreateAsync(vm);
 78→          break;
 79→        case SessionAction.Join:
 80→          await HandleJoinAsync(vm, result.DocumentId!);
 81→          break;
 82→        case SessionAction.Resume:
 83→          await HandleResumeAsync(vm, result.DocumentId!);
 84→          break;
 85→      }
 86→    }
 87→    catch(Exception ex)
 88→    {
 89→      vm.SyncStatus = $"Error: {ex.Message}";
 90→    }
 91→  }
 92→
 93→  async Task HandleCreateAsync(EditorViewModel vm)
 94→  {
 95→    if(vm.RepoService is null)
 96→    {
 97→      // Offline mode: create a standalone document
 98→      var automergeService = new AutomergeService();
 99→      vm.SetAutomergeService(automergeService);
100→      ShowEditor(null);
101→      return;
102→    }
103→
104→    await vm.RepoService.InitializeAsync();
105→    WireConnectionEvents(vm.RepoService);
106→
107→    // Create a new document via the repo
108→    var handle = vm.RepoService.Repo!.Create<object>();
109→    await handle.WhenReadyAsync();
110→
111→    // Initialize text CRDT on the document
112→    handle.Change(doc =>
113→    {
114→      doc.PutObject(doc.RootId, "content", AutomergeContainerType.Text);
115→    }, "Initialize text field");
116→
117→    var document = ((IDocHandle)handle).GetDocument()!;
118→    var automerge = AutomergeService.FromDocument(document);
119→    vm.SetAutomergeService(automerge);
120→    vm.DocHandle = handle;
121→
122→    ShowEditor(handle.DocumentId.ToString());
123→  }
124→
125→  async Task HandleJoinAsync(EditorViewModel vm, string documentId)
126→  {
127→    if(vm.RepoService is null)
128→    {
129→      vm.SyncStatus = "Cannot join: no server connection";
130→      return;
131→    }
132→
133→    await vm.RepoService.InitializeAsync();
134→    WireConnectionEvents(vm.RepoService);
135→
136→    vm.SyncStatus = "Joining document...";
137→
138→    var handle = await vm.RepoService.Repo!.Find<object>(documentId, TimeSpan.FromSeconds(30));
139→    if(handle is null)
140→    {
141→      vm.SyncStatus = "Document not found";
142→      return;
143→    }
144→
145→    await handle.WhenReadyAsync();
146→
147→    var document = ((IDocHandle)handle).GetDocument()!;
148→    var automerge = AutomergeService.FromDocument(document);
149→    vm.SetAutomergeService(automerge);
150→    vm.DocHandle = handle;
151→
152→    ShowEditor(handle.DocumentId.ToString());
153→  }
154→
155→  async Task HandleResumeAsync(EditorViewModel vm, string documentId)
156→  {
157→    if(vm.RepoService is null)
158→    {
159→      vm.SyncStatus = "Cannot resume: no server connection";
160→      return;
161→    }
162→
163→    await vm.RepoService.InitializeAsync();
164→    WireConnectionEvents(vm.RepoService);
165→
166→    vm.SyncStatus = "Resuming document...";
167→
168→    // Find will load from local storage first
169→    var handle = await vm.RepoService.Repo!.Find<object>(documentId, TimeSpan.FromSeconds(10));
170→    if(handle is null)
171→    {
172→      vm.SyncStatus = "Document not found in storage";
173→      return;
174→    }
175→
176→    await handle.WhenReadyAsync();
177→
178→    var document = ((IDocHandle)handle).GetDocument()!;
179→    var automerge = AutomergeService.FromDocument(document);
180→    vm.SetAutomergeService(automerge);
181→    vm.DocHandle = handle;
182→
183→    ShowEditor(handle.DocumentId.ToString());
184→  }
185→
186→  void WireConnectionEvents(RepoService repoService)
187→  {
188→    if(_statusBarVm is null)
189→    {
190→      return;
191→    }
192→
193→    _statusBarVm.PeerId = repoService.PeerId?.ToString();
194→    _statusBarVm.ServerUrl = repoService is { IsInitialized: true }
195→      ? "Connected"
196→      : "Offline";
197→
198→    repoService.ConnectionStateChanged += (_, state) =>
199→      Dispatcher.UIThread.Post(() =>
200→      {
201→        if(_statusBarVm is null)
202→        {
203→          return;
204→        }
205→
206→        _statusBarVm.ConnectionState = state switch
207→        {
208→          ConnectionState.Connected => DemoApp.Shared.ConnectionState.Connected,
209→          ConnectionState.Connecting => DemoApp.Shared.ConnectionState.Connecting,
210→          ConnectionState.Reconnecting => DemoApp.Shared.ConnectionState.Reconnecting,
211→          _ => DemoApp.Shared.ConnectionState.Disconnected
212→        };
213→      });
214→
215→    repoService.PeerCountChanged += (_, count) =>
216→      Dispatcher.UIThread.Post(() =>
217→      {
218→        if(_statusBarVm is not null)
219→        {
220→          _statusBarVm.PeerCount = count;
221→        }
222→      });
223→  }
224→
225→  void ShowEditor(string? documentId)
226→  {
227→    Dispatcher.UIThread.Post(() =>
228→    {
229→      SessionPanel.IsVisible = false;
230→      EditorPanel.IsVisible = true;
231→
232→      if(_statusBarVm is not null)
233→      {
234→        _statusBarVm.DocumentId = documentId ?? "local";
235→      }
236→
237→      LocalEditor.Focus();
238→    });
239→  }
240→}
