172→  /// <summary>
173→  /// Sets the AutomergeService for text operations (after document is created/loaded).
174→  /// </summary>
175→  internal void SetAutomergeService(AutomergeService service)
176→  {
177→    _automergeService = service;
178→    RefreshFromDocument();
179→  }
180→
181→  internal void ApplyTextChange(string newText)
182→  {
183→    if(_automergeService is null)
184→    {
185→      return;
186→    }
187→
188→    string currentText = _automergeService.GetText();
189→
190→    // Find the difference and apply as a splice operation.
191→    // This is a simplified diff: find common prefix and suffix.
192→    int prefixLen = 0;
193→    int minLen = Math.Min(currentText.Length, newText.Length);
194→    while(prefixLen < minLen && currentText[prefixLen] == newText[prefixLen])
195→    {
196→      prefixLen++;
197→    }
198→
199→    int suffixLen = 0;
200→    int maxSuffix = minLen - prefixLen;
201→    while(suffixLen < maxSuffix
202→      && currentText[currentText.Length - 1 - suffixLen] == newText[newText.Length - 1 - suffixLen])
203→    {
204→      suffixLen++;
205→    }
206→
207→    int deleteCount = currentText.Length - prefixLen - suffixLen;
208→    string insertText = newText.Substring(prefixLen, newText.Length - prefixLen - suffixLen);
209→
210→    if(deleteCount > 0 || insertText.Length > 0)
211→    {
212→      SaveCursorBeforeEdit();
213→      _automergeService.SpliceText((ulong)prefixLen, deleteCount, insertText);
214→    }
215→  }
216→
217→  internal void RefreshFromDocument()
218→  {
219→    if(_automergeService is null)
220→    {
221→      return;
222→    }
223→
224→    string text = _automergeService.GetText();
225→    if(_documentText != text)
226→    {
227→      _isRemoteUpdate = true;
228→      try
229→      {
230→        _documentText = text;
231→        this.RaisePropertyChanged(nameof(DocumentText));
232→      }
233→      finally
234→      {
235→        _isRemoteUpdate = false;
236→      }
237→    }
238→
239→    UpdateFormattingState();
240→  }
241→
242→  void OnDocHandleChanged(object? sender, DocHandleChangeEventArgs<object> e)
243→  {
244→    if(e.IsLocal)
245→    {
246→      return;
247→    }
248→
249→    _dispatcher(() =>
250→    {
251→      SaveCursorBeforeEdit();
252→      RefreshFromDocument();
253→      RestoreCursorAfterEdit();
254→    });
255→  }
256→
257→  void SaveCursorBeforeEdit()
258→  {
259→    if(_automergeService is null || _cursorPosition <= 0)
260→    {
261→      _savedCursor = null;
262→      return;
263→    }
264→
265→    try
266→    {
267→      ulong pos = (ulong)Math.Min(_cursorPosition, _automergeService.GetText().Length);
268→      if(pos > 0)
269→      {
270→        _savedCursor = _automergeService.GetCursor(pos - 1);
271→      }
272→      else
273→      {
274→        _savedCursor = null;
275→      }
276→    }
277→    catch(Exception)
278→    {
279→      _savedCursor = null;
280→    }
281→  }
282→
283→  void RestoreCursorAfterEdit()
284→  {
285→    if(_automergeService is null || _savedCursor is null)
286→    {
287→      return;
288→    }
289→
290→    try
291→    {
292→      ulong pos = _automergeService.GetCursorPosition(_savedCursor);
293→      CursorPosition = (int)(pos + 1);
294→    }
295→    catch(Exception)
296→    {
297→      // Cursor may be invalid after merge — leave at current position
298→    }
299→
300→    _savedCursor = null;
301→  }
302→
303→  void ToggleBold()
304→  {
305→    if(_automergeService is null || _selectionLength <= 0)
306→    {
307→      return;
308→    }
309→
310→    ulong start = (ulong)_cursorPosition;
311→    ulong end = (ulong)(_cursorPosition + _selectionLength);
312→
313→    if(_isBold)
314→    {
315→      _automergeService.UnmarkBold(start, end);
316→    }
317→    else
318→    {
319→      _automergeService.MarkBold(start, end, true);
320→    }
321→
322→    UpdateFormattingState();
323→  }
324→
325→  void ToggleItalic()
326→  {
327→    if(_automergeService is null || _selectionLength <= 0)
328→    {
329→      return;
330→    }
331→
332→    ulong start = (ulong)_cursorPosition;
333→    ulong end = (ulong)(_cursorPosition + _selectionLength);
334→
335→    if(_isItalic)
336→    {
337→      _automergeService.UnmarkItalic(start, end);
338→    }
339→    else
340→    {
341→      _automergeService.MarkItalic(start, end, true);
342→    }
343→
344→    UpdateFormattingState();
345→  }
346→
347→  void ToggleUnderline()
348→  {
349→    if(_automergeService is null || _selectionLength <= 0)
350→    {
351→      return;
352→    }
353→
354→    ulong start = (ulong)_cursorPosition;
355→    ulong end = (ulong)(_cursorPosition + _selectionLength);
356→
357→    if(_isUnderline)
358→    {
359→      _automergeService.UnmarkUnderline(start, end);
360→    }
361→    else
362→    {
363→      _automergeService.MarkUnderline(start, end, true);
364→    }
365→
366→    UpdateFormattingState();
367→  }
368→
369→  void UpdateFormattingState()
370→  {
371→    if(_disposed || _automergeService is null)
372→    {
373→      return;
374→    }
375→
376→    var marks = _automergeService.GetMarks();
377→    FormattingState state = FormattingState.FromMarks(marks, (ulong)_cursorPosition);
378→    IsBold = state.IsBold;
379→    IsItalic = state.IsItalic;
380→    IsUnderline = state.IsUnderline;
381→  }
382→
383→  void SaveDocument()
384→  {
385→    if(_automergeService is null)
386→    {
387→      SyncStatus = "No document loaded";
388→      return;
389→    }
390→
391→    byte[] saved = _automergeService.Save();
392→    SyncStatus = $"Saved ({saved.Length} bytes)";
393→  }
394→
395→  void ExportJson()
396→  {
397→    if(_automergeService is null)
398→    {
399→      SyncStatus = "No document loaded";
400→      return;
401→    }
402→
403→    string json = _automergeService.Document.HydrateJson();
404→    _logger.LogInformation("Document JSON: {Json}", json);
405→    SyncStatus = $"Exported JSON ({json.Length} chars)";
406→  }
407→
408→  public void Dispose()
409→  {
410→    if(!_disposed)
411→    {
412→      _disposed = true;
413→
414→      if(_docHandle is not null)
415→      {
416→        _docHandle.Changed -= OnDocHandleChanged;
417→      }
418→
419→      _automergeService?.Dispose();
420→      _repoService?.Dispose();
421→    }
422→  }
423→}
