 654→  /// <summary>
 655→  /// Creates a new document as a clone of an existing document.
 656→  /// </summary>
 657→  /// <typeparam name="T">The document content type.</typeparam>
 658→  /// <param name="source">The source handle to clone.</param>
 659→  /// <returns>A handle to the cloned document.</returns>
 660→  public DocHandle<T> Clone<T>(DocHandle<T> source)
 661→  {
 662→    if(source is null)
 663→      throw new ArgumentNullException(nameof(source));
 664→
 665→    ThrowIfDisposed();
 666→
 667→    // Generate new document ID
 668→    var newDocumentId = _idFactory is not null
 669→      ? DocumentId.FromBinary(_idFactory(Array.Empty<string>()).GetAwaiter().GetResult())
 670→      : DocumentId.Generate();
 671→
 672→    // Clone the underlying document
 673→    var sourceDocHandle = source;
 674→    var sourceDoc = sourceDocHandle.Doc();
 675→    var clonedDocBytes = (sourceDoc as AutomergeDocument)!.Save();
 676→    var clonedDoc = AutomergeDocument.Load(clonedDocBytes);
 677→
 678→    // Create new handle
 679→    var handle = new DocHandle<T>(
 680→      newDocumentId,
 681→      new DocHandleOptions<T> { IsNew = true, ViewFactory = CreateViewFactory<T>() },
 682→      clonedDoc);
 683→
 684→    _handleLock.Wait();
 685→    try
 686→    {
 687→      _handleCache[newDocumentId] = handle;
 688→    }
 689→    finally
 690→    {
 691→      _handleLock.Release();
 692→    }
 693→
 694→    // Register with subsystems
 695→    RegisterHandle(newDocumentId, handle);
 696→
 697→    // Emit event
 698→    DocumentLoaded?.Invoke(this,
 699→      new DocumentEventArgs { DocumentId = newDocumentId, Handle = handle });
 700→
 701→    return handle;
 702→  }
