 869→  #region Throttled Save
 870→
 871→  /// <summary>
 872→  /// Schedules a throttled save for a document.
 873→  /// </summary>
 874→  void ScheduleSave(string documentId)
 875→  {
 876→    if(_storage is null) return;
 877→
 878→    _saveLock.Wait();
 879→    try
 880→    {
 881→      // Cancel existing pending save
 882→      if(_pendingSaves.TryGetValue(documentId, out var existingCts))
 883→      {
 884→        existingCts.Cancel();
 885→        existingCts.Dispose();
 886→      }
 887→
 888→      // Schedule new save after debounce period
 889→      var cts = new CancellationTokenSource();
 890→      _pendingSaves[documentId] = cts;
 891→
 892→      Task.Delay(_saveDebounceRate, cts.Token)
 893→        .ContinueWith(async _ =>
 894→        {
 895→          if(cts.IsCancellationRequested) return;
 896→
 897→          await PerformSave(documentId);
 898→
 899→          _saveLock.Wait();
 900→          try
 901→          {
 902→            _pendingSaves.Remove(documentId);
 903→            cts.Dispose();
 904→          }
 905→          finally
 906→          {
 907→            _saveLock.Release();
 908→          }
 909→        }, TaskScheduler.Default);
 910→    }
 911→    finally
 912→    {
 913→      _saveLock.Release();
 914→    }
 915→  }
 916→
 917→  /// <summary>
 918→  /// Performs the actual save operation.
 919→  /// </summary>
 920→  async Task PerformSave(string documentId)
 921→  {
 922→    if(_storage is null) return;
 923→
 924→    await _handleLock.WaitAsync();
 925→    IDocHandle? handle;
 926→    try
 927→    {
 928→      if(!_handleCache.TryGetValue(documentId, out handle))
 929→      {
 930→        return; // Document no longer exists
 931→      }
 932→    }
 933→    finally
 934→    {
 935→      _handleLock.Release();
 936→    }
 937→
 938→    var doc = handle.GetDocument();
 939→    if(doc is not null)
 940→    {
 941→      await _storage.SaveDoc(documentId, doc);
 942→    }
 943→  }
