1080→  /// <summary>
1081→  /// Callback for synchronizer to request unknown document.
1082→  /// </summary>
1083→  void RequestDocument(string documentId)
1084→  {
1085→    // Trigger find operation in background
1086→    Task.Run(async () =>
1087→    {
1088→      try
1089→      {
1090→        await Find<object>(documentId);
1091→      }
1092→      catch
1093→      {
1094→        // Document unavailable, synchronizer will handle it
1095→      }
1096→    });
1097→  }
1098→
1099→  /// <summary>
1100→  /// Creates a view factory for the specified type.
1101→  /// </summary>
1102→  static Func<AutomergeDocument, T> CreateViewFactory<T>()
1103→  {
1104→    if(typeof(T) == typeof(object) || typeof(T) == typeof(AutomergeDocument))
1105→    {
1106→      return doc => (T)(object)doc;
1107→    }
1108→
1109→    // For other types, would need proper deserialization
1110→    return doc => (T)(object)doc;
1111→  }
1112→
1113→  #endregion
1114→
1115→  #region Persistence and Cleanup
1116→
1117→  /// <summary>
1118→  /// Flushes pending saves for specified documents (or all documents).
1119→  /// </summary>
1120→  /// <param name="documentIds">Optional list of document IDs to flush. If null, flushes all.</param>
1121→  public async Task Flush(IEnumerable<string>? documentIds = null)
1122→  {
1123→    if(_storage is null) return;
1124→
1125→    ThrowIfDisposed();
1126→
1127→    var idsToFlush = documentIds?.ToList() ?? _handleCache.Keys.ToList();
1128→
1129→    var saveTasks = new List<Task>();
1130→
1131→    foreach(var documentId in idsToFlush)
1132→    {
1133→      // Cancel pending throttled save
1134→      await _saveLock.WaitAsync();
1135→      try
1136→      {
1137→        if(_pendingSaves.TryGetValue(documentId, out var cts))
1138→        {
1139→          cts.Cancel();
1140→          _pendingSaves.Remove(documentId);
1141→        }
1142→      }
1143→      finally
1144→      {
1145→        _saveLock.Release();
1146→      }
1147→
1148→      // Perform immediate save
1149→      saveTasks.Add(PerformSave(documentId));
1150→    }
1151→
1152→    await Task.WhenAll(saveTasks);
1153→  }
1154→
1155→  /// <summary>
1156→  /// Removes a document from the cache without deleting from storage.
1157→  /// Useful for memory management.
1158→  /// </summary>
1159→  /// <param name="documentId">The document ID to remove from cache.</param>
1160→  public async Task RemoveFromCache(string documentId)
1161→  {
1162→    if(string.IsNullOrWhiteSpace(documentId))
1163→      throw new ArgumentException("Document ID cannot be null or whitespace", nameof(documentId));
1164→
1165→    ThrowIfDisposed();
1166→
1167→    // Flush first
1168→    await Flush(new[] { documentId });
1169→
1170→    await _handleLock.WaitAsync();
1171→    IDocHandle? handle;
1172→    try
1173→    {
1174→      if(!_handleCache.TryGetValue(documentId, out handle))
1175→      {
1176→        return;
1177→      }
1178→
1179→      _handleCache.Remove(documentId);
1180→    }
1181→    finally
1182→    {
1183→      _handleLock.Release();
1184→    }
1185→
1186→    // Unregister from synchronizer
1187→    _synchronizer.RemoveDocument(documentId);
1188→
1189→    // Unload handle
1190→    handle.Unload();
1191→  }
1192→
1193→  /// <summary>
1194→  /// Gracefully shuts down the repository, flushing all pending saves.
1195→  /// </summary>
1196→  public async Task Shutdown()
1197→  {
1198→    if(_isDisposed) return;
1199→
1200→    // Flush all documents
1201→    await Flush();
1202→
1203→    // Dispose
1204→    Dispose();
1205→  }
1206→
1207→
1208→  void ThrowIfDisposed()
1209→  {
1210→    if(_isDisposed)
1211→    {
1212→      throw new ObjectDisposedException(nameof(Repo));
1213→    }
1214→  }
1215→
1216→  #endregion
1217→}
