 87→  async void OnSessionResultReady(object? sender, EventArgs e)
 88→  {
 89→    if(_sessionVm?.Result is null || _viewModel is null)
 90→    {
 91→      return;
 92→    }
 93→
 94→    var result = _sessionVm.Result;
 95→
 96→    try
 97→    {
 98→      switch(result.Action)
 99→      {
100→        case SessionAction.Create:
