117→  async Task HandleCreateAsync()
118→  {
119→    if(_viewModel is null)
120→    {
121→      return;
122→    }
123→
124→    if(_viewModel.RepoService is null)
125→    {
126→      // Offline mode: create a standalone document
127→      var automergeService = new AutomergeService();
128→      _viewModel.SetAutomergeService(automergeService);
129→      ShowCanvas(null);
130→      return;
131→    }
132→
133→    await _viewModel.RepoService.InitializeAsync();
134→    WireConnectionEvents(_viewModel.RepoService);
135→
136→    // Create a new document via the repo
137→    var handle = _viewModel.RepoService.Repo!.Create<object>();
138→    await handle.WhenReadyAsync();
139→
140→    // Initialize canvas structure on the document
141→    handle.Change(doc =>
142→    {
143→      var layersListId = doc.PutObject(doc.RootId, "layers", AutomergeContainerType.List);
144→      var layerId = doc.ListInsertObject(layersListId, 0, AutomergeContainerType.Map);
145→      doc.PutString(layerId, "name", "Layer 1");
146→      doc.PutBoolean(layerId, "visible", true);
147→      doc.PutObject(layerId, "shapes", AutomergeContainerType.List);
148→    }, "Initialize canvas");
149→
150→    var document = ((IDocHandle)handle).GetDocument()!;
151→    var automerge = AutomergeService.FromDocument(document);
152→    _viewModel.SetAutomergeService(automerge);
153→    _viewModel.DocHandle = handle;
154→
155→    ShowCanvas(handle.DocumentId.ToString());
156→  }
