343→  void AddShapeToCanvas(ShapeViewModel shape)
344→  {
345→    if(_canvas is null)
346→    {
347→      return;
348→    }
349→
350→    Control shapeControl = CreateShapeControl(shape);
351→    Canvas.SetLeft(shapeControl, shape.X);
352→    Canvas.SetTop(shapeControl, shape.Y);
353→    _canvas.Children.Add(shapeControl);
354→    _shapeControls[shape] = shapeControl;
355→
356→    // Listen for property changes to update rendering
357→    shape.PropertyChanged += (_, args) =>
358→    {
359→      if(args.PropertyName is "X" or "Y")
360→      {
361→        Canvas.SetLeft(shapeControl, shape.X);
362→        Canvas.SetTop(shapeControl, shape.Y);
363→      }
364→      else if(args.PropertyName is "Width" or "Height")
365→      {
366→        shapeControl.Width = shape.Width;
367→        shapeControl.Height = shape.Height;
368→      }
369→      else if(args.PropertyName == "Color")
370→      {
371→        UpdateShapeColor(shapeControl, shape);
372→      }
373→    };
374→  }
