376→  Control CreateShapeControl(ShapeViewModel shape)
377→  {
378→    var brush = new SolidColorBrush(Color.Parse(shape.Color));
379→
380→    Control inner;
381→    if(shape.Type == ShapeType.Ellipse)
382→    {
383→      inner = new Ellipse
384→      {
385→        Width = shape.Width,
386→        Height = shape.Height,
387→        Fill = brush,
388→        Stroke = Brushes.Transparent,
389→        StrokeThickness = 2,
390→      };
391→    }
392→    else
393→    {
394→      inner = new Rectangle
395→      {
396→        Width = shape.Width,
397→        Height = shape.Height,
398→        Fill = brush,
399→        Stroke = Brushes.Transparent,
400→        StrokeThickness = 2,
401→        RadiusX = 2,
402→        RadiusY = 2,
403→      };
404→    }
405→
406→    var wrapper = new Border
407→    {
408→      Child = inner,
409→      Tag = shape,
410→      Cursor = new Cursor(StandardCursorType.Hand),
411→    };
412→
413→    wrapper.PointerPressed += OnShapePointerPressed;
414→
415→    return wrapper;
416→  }
