527→    {
528→      double dx = point.X - _dragStart.X;
529→      double dy = point.Y - _dragStart.Y;
530→      double newX = _dragTarget.X + dx;
531→      double newY = _dragTarget.Y + dy;
532→
533→      // Update VM and visual immediately (commit on release)
534→      _dragTarget.X = newX;
535→      _dragTarget.Y = newY;
536→      _dragStart = point;
537→
538→      // Update selection visual
539→      if(_selectionBorder is not null)
540→      {
541→        Canvas.SetLeft(_selectionBorder, newX - 2);
542→        Canvas.SetTop(_selectionBorder, newY - 2);
543→      }
544→    }
545→    else if(_isDrawing && _drawPreview is not null)
546→    {
547→      double x = Math.Min(_drawStart.X, point.X);
548→      double y = Math.Min(_drawStart.Y, point.Y);
549→      double w = Math.Abs(point.X - _drawStart.X);
550→      double h = Math.Abs(point.Y - _drawStart.Y);
551→
552→      Canvas.SetLeft(_drawPreview, x);
553→      Canvas.SetTop(_drawPreview, y);
554→      _drawPreview.Width = w;
555→      _drawPreview.Height = h;
556→    }
557→  }
558→
559→  void OnCanvasPointerReleased(object? sender, PointerReleasedEventArgs e)
560→  {
561→    if(_canvas is null || _viewModel is null)
562→    {
563→      return;
564→    }
565→
566→    var point = e.GetPosition(_canvas);
567→
568→    if(_isDragging && _dragTarget is not null)
569→    {
570→      // Commit the move to the CRDT
571→      _viewModel.MoveSelectedShape(_dragTarget.X, _dragTarget.Y);
572→      _isDragging = false;
573→      _dragTarget = null;
574→    }
575→    else if(_isDrawing)
576→    {
577→      _isDrawing = false;
578→
579→      // Remove preview
580→      if(_drawPreview is not null)
581→      {
582→        _canvas.Children.Remove(_drawPreview);
583→        _drawPreview = null;
584→      }
585→
586→      double x = Math.Min(_drawStart.X, point.X);
587→      double y = Math.Min(_drawStart.Y, point.Y);
588→      double w = Math.Abs(point.X - _drawStart.X);
589→      double h = Math.Abs(point.Y - _drawStart.Y);
590→
591→      // Minimum size to avoid accidental micro-shapes
592→      if(w < 10)
593→      {
594→        w = 80;
595→      }
596→
597→      if(h < 10)
598→      {
599→        h = 60;
600→      }
601→
602→      _viewModel.AddShape(x, y, w, h);
603→
604→      // Select the newly created shape
605→      if(_viewModel.Shapes.Count > 0)
606→      {
607→        _viewModel.SelectedShape = _viewModel.Shapes[^1];
608→        UpdateSelectionVisual();
609→      }
610→    }
611→  }
612→
613→  void OnShapePointerPressed(object? sender, PointerPressedEventArgs e)
614→  {
615→    if(_canvas is null || _viewModel is null)
616→    {
617→      return;
618→    }
619→
620→    if(sender is Border { Tag: ShapeViewModel shape })
621→    {
622→      _viewModel.SelectedShape = shape;
623→      UpdateSelectionVisual();
624→
625→      // Start dragging
626→      _isDragging = true;
627→      _isDrawing = false;
628→      _dragStart = e.GetPosition(_canvas);
629→      _dragTarget = shape;
630→      e.Handled = true;
631→    }
632→  }
633→
634→  // --- Tool selection ---
635→
636→  void OnRectangleToolClick(object? sender, RoutedEventArgs e)
637→  {
638→    if(_viewModel is null)
639→    {
640→      return;
641→    }
642→
643→    _viewModel.SelectedTool = ShapeType.Rectangle;
644→    var rectTool = this.FindControl<ToggleButton>("RectangleTool");
645→    var ellipseTool = this.FindControl<ToggleButton>("EllipseTool");
646→    if(rectTool is not null)
647→    {
648→      rectTool.IsChecked = true;
649→    }
650→
651→    if(ellipseTool is not null)
652→    {
653→      ellipseTool.IsChecked = false;
654→    }
655→  }
656→
657→  void OnEllipseToolClick(object? sender, RoutedEventArgs e)
658→  {
659→    if(_viewModel is null)
660→    {
661→      return;
662→    }
663→
664→    _viewModel.SelectedTool = ShapeType.Ellipse;
665→    var rectTool = this.FindControl<ToggleButton>("RectangleTool");
666→    var ellipseTool = this.FindControl<ToggleButton>("EllipseTool");
667→    if(rectTool is not null)
668→    {
669→      rectTool.IsChecked = false;
670→    }
671→
672→    if(ellipseTool is not null)
673→    {
674→      ellipseTool.IsChecked = true;
675→    }
676→  }
677→
678→  // --- Color selection ---
679→
680→  void OnColorClick(object? sender, RoutedEventArgs e)
681→  {
682→    if(_viewModel is null || sender is not Button { Tag: string color })
683→    {
684→      return;
685→    }
