687→    _viewModel.SelectedColor = color;
688→
689→    // If a shape is selected, recolor it
690→    if(_viewModel.SelectedShape is not null)
691→    {
692→      _viewModel.RecolorSelectedShape();
693→      UpdateSelectionVisual();
694→    }
695→  }
