130→  /// <summary>
131→  /// Adds a shape at the specified canvas position using the current tool and color.
132→  /// </summary>
133→  public void AddShape(double x, double y, double width, double height)
134→  {
135→    if(_service is null)
136→    {
137→      return;
138→    }
139→
140→    _shapeCounter++;
141→    string name = $"{_selectedTool} {_shapeCounter}";
142→    var shape = _service.AddShape(name, _selectedTool, x, y, width, height, _selectedColor);
143→
144→    var vm = ToShapeViewModel(shape);
145→    Shapes.Add(vm);
146→
147→    // Also add to the first layer's VM shape list
148→    if(Layers.Count > 0)
149→    {
150→      Layers[0].Shapes.Add(vm);
151→    }
152→
153→    StatusText = $"Added {name}";
154→  }
