156→  /// <summary>
157→  /// Moves the selected shape to a new position.
158→  /// </summary>
159→  public void MoveSelectedShape(double x, double y)
160→  {
161→    if(_selectedShape is null || _service is null)
162→    {
163→      return;
164→    }
165→
166→    _service.MoveShape(_selectedShape.ObjectId, x, y);
167→    _selectedShape.X = x;
168→    _selectedShape.Y = y;
169→    StatusText = $"Moved {_selectedShape.Name}";
170→  }
171→
172→  /// <summary>
173→  /// Resizes the selected shape.
174→  /// </summary>
175→  public void ResizeSelectedShape(double width, double height)
176→  {
177→    if(_selectedShape is null || _service is null)
178→    {
179→      return;
180→    }
181→
182→    _service.ResizeShape(_selectedShape.ObjectId, width, height);
183→    _selectedShape.Width = width;
184→    _selectedShape.Height = height;
185→    StatusText = $"Resized {_selectedShape.Name}";
186→  }
187→
188→  /// <summary>
189→  /// Deletes the currently selected shape.
190→  /// </summary>
191→  public void DeleteSelectedShape()
192→  {
193→    if(_selectedShape is null || _service is null)
194→    {
195→      return;
196→    }
197→
198→    int shapeIndex = Shapes.IndexOf(_selectedShape);
199→    if(shapeIndex < 0)
200→    {
201→      return;
202→    }
203→
204→    // Find which layer contains this shape and remove from that layer
205→    int layerIndex = FindLayerIndexForShape(_selectedShape);
206→    if(layerIndex >= 0)
207→    {
208→      int indexInLayer = FindShapeIndexInLayer(layerIndex, _selectedShape);
209→      if(indexInLayer >= 0)
210→      {
211→        _service.RemoveShape((ulong)layerIndex, (ulong)indexInLayer);
212→        Layers[layerIndex].Shapes.Remove(_selectedShape);
213→      }
214→    }
215→
216→    string name = _selectedShape.Name;
217→    Shapes.Remove(_selectedShape);
218→    SelectedShape = null;
219→    StatusText = $"Deleted {name}";
220→  }
221→
222→  /// <summary>
223→  /// Recolors the selected shape using the current selected color.
224→  /// </summary>
225→  public void RecolorSelectedShape()
226→  {
227→    if(_selectedShape is null || _service is null)
228→    {
229→      return;
230→    }
231→
232→    _service.RecolorShape(_selectedShape.ObjectId, _selectedColor);
233→    _selectedShape.Color = _selectedColor;
234→    StatusText = $"Recolored {_selectedShape.Name}";
235→  }
236→
237→  void AddLayer()
238→  {
239→    if(_service is null)
240→    {
241→      return;
242→    }
243→
244→    string name = $"Layer {Layers.Count + 1}";
245→    var layer = _service.AddLayer(name);
246→    Layers.Add(ToLayerViewModel(layer));
247→    StatusText = $"Added layer: {name}";
248→  }
