250→  void Save()
251→  {
252→    if(_service is null)
253→    {
254→      StatusText = "No document loaded";
255→      return;
256→    }
257→
258→    byte[] saved = _service.Save();
259→    StatusText = $"Saved ({saved.Length} bytes)";
260→  }
261→
262→  internal void RefreshFromDocument()
263→  {
264→    if(_service is null)
265→    {
266→      return;
267→    }
268→
269→    Shapes.Clear();
270→    Layers.Clear();
271→    _shapeCounter = 0;
272→    var layers = _service.ReadCanvas();
273→    foreach(var layer in layers)
274→    {
275→      var layerVm = ToLayerViewModel(layer);
276→      Layers.Add(layerVm);
277→      foreach(var shapeVm in layerVm.Shapes)
278→      {
279→        Shapes.Add(shapeVm);
280→        _shapeCounter++;
281→      }
282→    }
283→
284→    SelectedShape = null;
285→  }
