287→  void OnDocHandleChanged(object? sender, DocHandleChangeEventArgs<object> e)
288→  {
289→    if(e.IsLocal)
290→    {
291→      return;
292→    }
293→
294→    _dispatcher(() => RefreshFromDocument());
295→  }
