297→  int FindLayerIndexForShape(ShapeViewModel shape)
298→  {
299→    for(int i = 0; i < Layers.Count; i++)
300→    {
301→      if(Layers[i].Shapes.Contains(shape))
302→      {
303→        return i;
304→      }
305→    }
306→
307→    return -1;
308→  }
309→
310→  int FindShapeIndexInLayer(int layerIndex, ShapeViewModel shape)
311→  {
312→    return Layers[layerIndex].Shapes.IndexOf(shape);
313→  }
314→
315→  static LayerViewModel ToLayerViewModel(Layer layer)
316→  {
317→    var vm = new LayerViewModel(layer.ObjectId, layer.ShapesListId, layer.Name, layer.IsVisible);
318→    foreach(var shape in layer.Shapes)
319→    {
320→      vm.Shapes.Add(ToShapeViewModel(shape));
321→    }
322→
323→    return vm;
324→  }
325→
326→  static ShapeViewModel ToShapeViewModel(CanvasObject shape)
327→  {
328→    return new ShapeViewModel(
329→      shape.ObjectId,
330→      shape.Name,
331→      shape.Type,
332→      shape.X,
333→      shape.Y,
334→      shape.Width,
335→      shape.Height,
336→      shape.Color,
337→      shape.ZOrder);
338→  }
339→
340→  public void Dispose()
341→  {
342→    if(!_disposed)
343→    {
344→      _disposed = true;
345→
346→      if(_docHandle is not null)
347→      {
348→        _docHandle.Changed -= OnDocHandleChanged;
349→      }
350→
351→      _service?.Dispose();
352→      _repoService?.Dispose();
353→    }
354→  }
355→}
