  3→using DemoApp.CollaborativeDrawing.Models;
  4→using Ray.Automerge;
  5→
  6→namespace DemoApp.CollaborativeDrawing.Services;
  7→
  8→/// <summary>
  9→/// Wraps <see cref="AutomergeDocument"/> to provide CRUD operations
 10→/// for shapes and layers on a collaborative canvas.
 11→/// </summary>
 12→/// <remarks>
 13→/// Document schema:
 14→/// <code>
 15→/// root (map)
 16→///   └── "layers" (list)
 17→///         └── [0..n] (map)
 18→///               ├── "name"      (string)
 19→///               ├── "visible"   (boolean)
 20→///               └── "shapes"    (list)
 21→///                     └── [0..m] (map)
 22→///                           ├── "name"    (string)
 23→///                           ├── "type"    (string)  — "Rectangle" | "Ellipse"
 24→///                           ├── "x"       (f64)
 25→///                           ├── "y"       (f64)
 26→///                           ├── "width"   (f64)
 27→///                           ├── "height"  (f64)
 28→///                           ├── "color"   (string)  — hex "#RRGGBB"
 29→///                           └── "zOrder"  (int64)
 30→/// </code>
 31→/// </remarks>
 32→sealed class AutomergeService : IDisposable
 33→{
 34→  readonly AutomergeDocument _document;
 35→  readonly AutomergeObjectId _layersListId;
 36→  readonly bool _ownsDocument;
 37→  bool _disposed;
 38→
 39→  public AutomergeService()
 40→  {
 41→    _document = AutomergeDocument.Create();
 42→    _layersListId = _document.PutObject(_document.RootId, "layers", AutomergeContainerType.List);
 43→
 44→    // Create a default layer
 45→    var layerId = _document.ListInsertObject(_layersListId, 0, AutomergeContainerType.Map);
 46→    _document.PutString(layerId, "name", "Layer 1");
 47→    _document.PutBoolean(layerId, "visible", true);
 48→    _document.PutObject(layerId, "shapes", AutomergeContainerType.List);
 49→
 50→    _document.Commit("Initialize canvas");
 51→    _ownsDocument = true;
 52→  }
 53→
 54→  AutomergeService(AutomergeDocument document, AutomergeObjectId layersListId, bool ownsDocument)
 55→  {
 56→    _document = document;
 57→    _layersListId = layersListId;
 58→    _ownsDocument = ownsDocument;
 59→  }
 60→
 61→  /// <summary>
 62→  /// Gets the underlying document for sync operations.
 63→  /// </summary>
 64→  public AutomergeDocument Document => _document;
 65→
 66→  /// <summary>
 67→  /// Adds a shape to the default (first) layer.
 68→  /// </summary>
 69→  public CanvasObject AddShape(string name, ShapeType type, double x, double y, double width, double height, string color)
 70→  {
 71→    ThrowIfDisposed();
 72→    var defaultLayer = _document.ListGetObject(_layersListId, 0)
 73→      ?? throw new InvalidOperationException("No default layer found.");
 74→    var shapesListId = _document.GetObject(defaultLayer, "shapes")
 75→      ?? throw new InvalidOperationException("Default layer has no shapes list.");
 76→
 77→    return AddShapeToLayer(shapesListId, name, type, x, y, width, height, color);
 78→  }
 79→
 80→  /// <summary>
 81→  /// Adds a shape to a specific layer's shapes list.
 82→  /// </summary>
 83→  public CanvasObject AddShapeToLayer(
 84→    AutomergeObjectId shapesListId,
 85→    string name,
 86→    ShapeType type,
 87→    double x,
 88→    double y,
 89→    double width,
 90→    double height,
 91→    string color)
 92→  {
 93→    ThrowIfDisposed();
 94→    ulong index = _document.ListLength(shapesListId);
 95→    var shapeId = _document.ListInsertObject(shapesListId, index, AutomergeContainerType.Map);
 96→    _document.PutString(shapeId, "name", name);
 97→    _document.PutString(shapeId, "type", type.ToString());
 98→    _document.PutDouble(shapeId, "x", x);
 99→    _document.PutDouble(shapeId, "y", y);
100→    _document.PutDouble(shapeId, "width", width);
101→    _document.PutDouble(shapeId, "height", height);
102→    _document.PutString(shapeId, "color", color);
103→    _document.PutInt64(shapeId, "zOrder", (long)index);
104→    _document.Commit($"Add shape: {name}");
105→
106→    return new CanvasObject
107→    {
108→      ObjectId = shapeId,
109→      Name = name,
110→      Type = type,
111→      X = x,
112→      Y = y,
113→      Width = width,
114→      Height = height,
115→      Color = color,
116→      ZOrder = (long)index,
117→    };
118→  }
119→
120→  /// <summary>
121→  /// Moves a shape to a new position.
122→  /// </summary>
123→  public void MoveShape(AutomergeObjectId shapeId, double x, double y)
124→  {
125→    ThrowIfDisposed();
126→    _document.PutDouble(shapeId, "x", x);
127→    _document.PutDouble(shapeId, "y", y);
128→    _document.Commit("Move shape");
129→  }
130→
131→  /// <summary>
132→  /// Resizes a shape.
133→  /// </summary>
134→  public void ResizeShape(AutomergeObjectId shapeId, double width, double height)
135→  {
136→    ThrowIfDisposed();
137→    _document.PutDouble(shapeId, "width", width);
138→    _document.PutDouble(shapeId, "height", height);
139→    _document.Commit("Resize shape");
140→  }
141→
142→  /// <summary>
143→  /// Changes a shape's fill color.
144→  /// </summary>
145→  public void RecolorShape(AutomergeObjectId shapeId, string color)
146→  {
147→    ThrowIfDisposed();
148→    _document.PutString(shapeId, "color", color);
149→    _document.Commit("Recolor shape");
150→  }
151→
152→  /// <summary>
153→  /// Removes a shape from a layer by layer index and shape index.
154→  /// </summary>
155→  public void RemoveShape(ulong layerIndex, ulong shapeIndex)
156→  {
157→    ThrowIfDisposed();
158→    var layerId = _document.ListGetObject(_layersListId, layerIndex)
159→      ?? throw new InvalidOperationException($"No layer at index {layerIndex}.");
160→    var shapesListId = _document.GetObject(layerId, "shapes")
161→      ?? throw new InvalidOperationException("Layer has no shapes list.");
162→
163→    _document.ListRemove(shapesListId, shapeIndex);
164→    _document.Commit($"Remove shape at layer {layerIndex}, index {shapeIndex}");
165→  }
166→
167→  /// <summary>
168→  /// Adds a new layer at the end of the layers list.
169→  /// </summary>
170→  public Layer AddLayer(string name)
171→  {
172→    ThrowIfDisposed();
173→    ulong index = _document.ListLength(_layersListId);
174→    var layerId = _document.ListInsertObject(_layersListId, index, AutomergeContainerType.Map);
175→    _document.PutString(layerId, "name", name);
176→    _document.PutBoolean(layerId, "visible", true);
177→    var shapesListId = _document.PutObject(layerId, "shapes", AutomergeContainerType.List);
178→    _document.Commit($"Add layer: {name}");
179→
180→    return new Layer
181→    {
182→      ObjectId = layerId,
183→      ShapesListId = shapesListId,
184→      Name = name,
185→      IsVisible = true,
186→    };
187→  }
188→
189→  /// <summary>
190→  /// Removes a layer by its index.
191→  /// </summary>
192→  public void RemoveLayer(ulong index)
193→  {
194→    ThrowIfDisposed();
195→    _document.ListRemove(_layersListId, index);
196→    _document.Commit($"Remove layer at {index}");
197→  }
198→
199→  /// <summary>
200→  /// Toggles a layer's visibility.
201→  /// </summary>
202→  public void ToggleLayerVisibility(AutomergeObjectId layerId, bool isVisible)
203→  {
204→    ThrowIfDisposed();
205→    _document.PutBoolean(layerId, "visible", isVisible);
206→    _document.Commit($"Set layer visibility: {isVisible}");
207→  }
208→
209→  /// <summary>
210→  /// Reads the full canvas state from the document.
211→  /// </summary>
212→  public List<Layer> ReadCanvas()
213→  {
214→    ThrowIfDisposed();
215→    var layers = new List<Layer>();
216→    ulong layerCount = _document.ListLength(_layersListId);
217→
218→    for(ulong i = 0; i < layerCount; i++)
219→    {
220→      var layerId = _document.ListGetObject(_layersListId, i);
221→      if(layerId is null)
222→      {
223→        continue;
224→      }
225→
226→      var shapesListId = _document.GetObject(layerId, "shapes");
227→      if(shapesListId is null)
228→      {
229→        continue;
230→      }
231→
232→      var layer = new Layer
233→      {
234→        ObjectId = layerId,
235→        ShapesListId = shapesListId,
236→        Name = _document.GetString(layerId, "name") ?? string.Empty,
237→        IsVisible = _document.GetBoolean(layerId, "visible") ?? true,
238→      };
239→
240→      ulong shapeCount = _document.ListLength(shapesListId);
241→      for(ulong j = 0; j < shapeCount; j++)
242→      {
243→        var shapeId = _document.ListGetObject(shapesListId, j);
244→        if(shapeId is null)
245→        {
246→          continue;
247→        }
248→
249→        string typeStr = _document.GetString(shapeId, "type") ?? "Rectangle";
250→        var shapeType = Enum.TryParse<ShapeType>(typeStr, out var parsed) ? parsed : ShapeType.Rectangle;
251→
252→        layer.Shapes.Add(new CanvasObject
253→        {
254→          ObjectId = shapeId,
255→          Name = _document.GetString(shapeId, "name") ?? string.Empty,
256→          Type = shapeType,
257→          X = _document.GetDouble(shapeId, "x") ?? 0,
258→          Y = _document.GetDouble(shapeId, "y") ?? 0,
259→          Width = _document.GetDouble(shapeId, "width") ?? 0,
260→          Height = _document.GetDouble(shapeId, "height") ?? 0,
261→          Color = _document.GetString(shapeId, "color") ?? "#000000",
262→          ZOrder = _document.GetInt64(shapeId, "zOrder") ?? 0,
263→        });
264→      }
265→
266→      layers.Add(layer);
267→    }
268→
269→    return layers;
270→  }
271→
272→  /// <summary>
273→  /// Saves the full document state as a byte array.
274→  /// </summary>
275→  public byte[] Save()
276→  {
277→    ThrowIfDisposed();
278→    return _document.Save();
279→  }
280→
281→  /// <summary>
282→  /// Loads a canvas from a previously saved byte array.
283→  /// </summary>
284→  public static AutomergeService Load(byte[] data)
285→  {
286→    var doc = AutomergeDocument.Load(data);
287→    var layersListId = doc.GetObject(doc.RootId, "layers")
288→      ?? throw new InvalidOperationException("Saved document does not contain a 'layers' list.");
289→
290→    return new AutomergeService(doc, layersListId, ownsDocument: true);
291→  }
292→
293→  /// <summary>
294→  /// Creates an AutomergeService that wraps an existing document, initializing the canvas
295→  /// structure if it doesn't already exist. The document is NOT owned (not disposed by this service).
296→  /// </summary>
297→  public static AutomergeService FromDocument(AutomergeDocument document)
298→  {
299→    ArgumentNullException.ThrowIfNull(document);
300→
301→    var keys = document.GetKeys(document.RootId).ToList();
302→    AutomergeObjectId layersListId;
303→
304→    if(keys.Contains("layers"))
305→    {
306→      layersListId = document.GetObject(document.RootId, "layers")
307→        ?? throw new InvalidOperationException("Could not resolve 'layers' list object.");
308→    }
309→    else
310→    {
311→      layersListId = document.PutObject(document.RootId, "layers", AutomergeContainerType.List);
312→
313→      var layerId = document.ListInsertObject(layersListId, 0, AutomergeContainerType.Map);
314→      document.PutString(layerId, "name", "Layer 1");
315→      document.PutBoolean(layerId, "visible", true);
316→      document.PutObject(layerId, "shapes", AutomergeContainerType.List);
317→
318→      document.Commit("Initialize canvas");
319→    }
320→
321→    return new AutomergeService(document, layersListId, ownsDocument: false);
322→  }
323→
324→  /// <summary>
325→  /// Gets the JSON representation of the document.
326→  /// </summary>
327→  public string HydrateJson()
328→  {
329→    ThrowIfDisposed();
330→    return _document.HydrateJson();
331→  }
332→
333→  public void Dispose()
334→  {
335→    if(!_disposed)
336→    {
337→      _disposed = true;
338→      if(_ownsDocument)
339→      {
340→        _document.Dispose();
341→      }
342→    }
343→  }
344→
345→  void ThrowIfDisposed()
346→  {
347→    ObjectDisposedException.ThrowIf(_disposed, this);
348→  }
349→}
