 26→  BoardViewModel? ViewModel => DataContext as BoardViewModel;
 27→
 28→  void OnLoaded(object? sender, EventArgs e)
 29→  {
 30→    _sessionVm = new DocumentSessionDialogViewModel();
 31→    _sessionVm.ResultReady += OnSessionResultReady;
 32→
 33→    SessionDialog.DataContext = _sessionVm;
 34→
 35→    _statusBarVm = new ConnectionStatusBarViewModel();
 36→    StatusBar.DataContext = _statusBarVm;
 37→
 38→    // Load stored documents if RepoService is available
 39→    if(ViewModel?.RepoService is not null)
 40→    {
 41→      _sessionVm.LoadStoredDocuments(ViewModel.RepoService.StorageDirectory);
 42→    }
 43→  }
 44→
 45→  async void OnSessionResultReady(object? sender, EventArgs e)
 46→  {
 47→    if(_sessionVm?.Result is null || ViewModel is null)
 48→    {
 49→      return;
 50→    }
 51→
 52→    var result = _sessionVm.Result;
 53→
 54→    try
 55→    {
 56→      switch(result.Action)
 57→      {
 58→        case SessionAction.Create:
 59→          await HandleCreateAsync(ViewModel);
 60→          break;
 61→        case SessionAction.Join:
 62→          await HandleJoinAsync(ViewModel, result.DocumentId!);
 63→          break;
 64→        case SessionAction.Resume:
 65→          await HandleResumeAsync(ViewModel, result.DocumentId!);
 66→          break;
 67→      }
 68→    }
 69→    catch(Exception ex)
 70→    {
 71→      ViewModel.StatusText = $"Error: {ex.Message}";
 72→    }
 73→  }
 74→
 75→  async Task HandleCreateAsync(BoardViewModel vm)
 76→  {
 77→    if(vm.RepoService is null)
 78→    {
 79→      // Offline mode: create a standalone document
 80→      var automergeService = new AutomergeService();
 81→      vm.SetAutomergeService(automergeService);
 82→      vm.SeedAndRefresh();
 83→      ShowEditor(null);
 84→      return;
 85→    }
 86→
 87→    await vm.RepoService.InitializeAsync();
 88→    WireConnectionEvents(vm.RepoService);
 89→
 90→    // Create a new document via the repo
 91→    var handle = vm.RepoService.Repo!.Create<object>();
 92→    await handle.WhenReadyAsync();
 93→
 94→    // Initialize board schema on the document
 95→    handle.Change(doc =>
 96→    {
 97→      doc.PutObject(doc.RootId, "columns", AutomergeContainerType.List);
 98→    }, "Initialize board columns");
 99→
100→    var document = ((IDocHandle)handle).GetDocument()!;
101→    var automerge = AutomergeService.FromDocument(document);
102→    vm.SetAutomergeService(automerge);
103→    vm.DocHandle = handle;
104→
105→    // Seed default columns
106→    vm.SeedAndRefresh();
107→
108→    ShowEditor(handle.DocumentId.ToString());
109→  }
110→
111→  async Task HandleJoinAsync(BoardViewModel vm, string documentId)
112→  {
113→    if(vm.RepoService is null)
114→    {
115→      vm.StatusText = "Cannot join: no server connection";
116→      return;
117→    }
118→
119→    await vm.RepoService.InitializeAsync();
120→    WireConnectionEvents(vm.RepoService);
121→
122→    vm.StatusText = "Joining board...";
123→
124→    var handle = await vm.RepoService.Repo!.Find<object>(documentId, TimeSpan.FromSeconds(30));
125→    if(handle is null)
126→    {
127→      vm.StatusText = "Board not found";
128→      return;
129→    }
130→
131→    await handle.WhenReadyAsync();
132→
133→    var document = ((IDocHandle)handle).GetDocument()!;
134→    var automerge = AutomergeService.FromDocument(document);
135→    vm.SetAutomergeService(automerge);
136→    vm.DocHandle = handle;
137→
138→    // Read board state from the joined document
139→    vm.RefreshFromDocument();
140→
141→    ShowEditor(handle.DocumentId.ToString());
142→  }
143→
144→  async Task HandleResumeAsync(BoardViewModel vm, string documentId)
145→  {
146→    if(vm.RepoService is null)
147→    {
148→      vm.StatusText = "Cannot resume: no server connection";
149→      return;
150→    }
151→
152→    await vm.RepoService.InitializeAsync();
153→    WireConnectionEvents(vm.RepoService);
154→
155→    vm.StatusText = "Resuming board...";
156→
157→    var handle = await vm.RepoService.Repo!.Find<object>(documentId, TimeSpan.FromSeconds(10));
158→    if(handle is null)
159→    {
160→      vm.StatusText = "Board not found in storage";
161→      return;
162→    }
163→
164→    await handle.WhenReadyAsync();
165→
166→    var document = ((IDocHandle)handle).GetDocument()!;
167→    var automerge = AutomergeService.FromDocument(document);
168→    vm.SetAutomergeService(automerge);
169→    vm.DocHandle = handle;
170→
171→    // Read board state from storage
172→    vm.RefreshFromDocument();
173→
174→    ShowEditor(handle.DocumentId.ToString());
175→  }
