  8→/// <summary>
  9→/// Wraps <see cref="AutomergeDocument"/> to provide CRUD operations
 10→/// for columns and tasks on the task board.
 11→/// </summary>
 12→/// <remarks>
 13→/// Document schema:
 14→/// <code>
 15→/// root (map)
 16→///   └── "columns" (list)
 17→///         └── [0..n] (map)
 18→///               ├── "name"   (string)
 19→///               ├── "order"  (int64)
 20→///               └── "tasks"  (list)
 21→///                     └── [0..m] (map)
 22→///                           ├── "title"       (string)
 23→///                           ├── "description" (string)
 24→///                           ├── "status"      (string)
 25→///                           └── "votes"       (counter)
 26→/// </code>
 27→/// </remarks>
 28→sealed class AutomergeService : IDisposable
 29→{
 30→  readonly AutomergeDocument _document;
 31→  readonly AutomergeObjectId _columnsListId;
 32→  readonly bool _ownsDocument;
 33→  bool _disposed;
 34→
 35→  public AutomergeService()
 36→  {
 37→    _document = AutomergeDocument.Create();
 38→    _columnsListId = _document.PutObject(_document.RootId, "columns", AutomergeContainerType.List);
 39→    _document.Commit("Initialize board");
 40→    _ownsDocument = true;
 41→  }
 42→
 43→  AutomergeService(AutomergeDocument document, AutomergeObjectId columnsListId, bool ownsDocument)
 44→  {
 45→    _document = document;
 46→    _columnsListId = columnsListId;
 47→    _ownsDocument = ownsDocument;
 48→  }
 49→
 50→  /// <summary>
 51→  /// Gets the underlying document for sync operations.
 52→  /// </summary>
 53→  public AutomergeDocument Document => _document;
 54→
 55→  /// <summary>
 56→  /// Adds a new column at the end of the board.
 57→  /// </summary>
 58→  public Column AddColumn(string name)
 59→  {
 60→    ThrowIfDisposed();
 61→    ulong index = _document.ListLength(_columnsListId);
 62→    var columnId = _document.ListInsertObject(_columnsListId, index, AutomergeContainerType.Map);
 63→    _document.PutString(columnId, "name", name);
 64→    _document.PutInt64(columnId, "order", (long)index);
 65→    var tasksListId = _document.PutObject(columnId, "tasks", AutomergeContainerType.List);
 66→    _document.Commit($"Add column: {name}");
 67→
 68→    return new Column
 69→    {
 70→      ObjectId = columnId,
 71→      TasksListId = tasksListId,
 72→      Name = name,
 73→      Order = (long)index,
 74→    };
 75→  }
 76→
 77→  /// <summary>
 78→  /// Removes a column by its index in the columns list.
 79→  /// </summary>
 80→  public void RemoveColumn(ulong index)
 81→  {
 82→    ThrowIfDisposed();
 83→    _document.ListRemove(_columnsListId, index);
 84→    _document.Commit($"Remove column at {index}");
 85→  }
 86→
 87→  /// <summary>
 88→  /// Updates a column's name.
 89→  /// </summary>
 90→  public void UpdateColumnName(AutomergeObjectId columnId, string newName)
 91→  {
 92→    ThrowIfDisposed();
 93→    _document.PutString(columnId, "name", newName);
 94→    _document.Commit($"Rename column to: {newName}");
 95→  }
 96→
 97→  /// <summary>
 98→  /// Adds a new task to the specified column's task list.
 99→  /// </summary>
100→  public TaskItem AddTask(AutomergeObjectId tasksListId, string title, string description, string status)
101→  {
102→    ThrowIfDisposed();
103→    ulong index = _document.ListLength(tasksListId);
104→    var taskId = _document.ListInsertObject(tasksListId, index, AutomergeContainerType.Map);
105→    _document.PutString(taskId, "title", title);
106→    _document.PutString(taskId, "description", description);
107→    _document.PutString(taskId, "status", status);
108→    _document.PutCounter(taskId, "votes", 0);
109→    _document.Commit($"Add task: {title}");
110→
111→    return new TaskItem
112→    {
113→      ObjectId = taskId,
114→      Title = title,
115→      Description = description,
116→      Status = status,
117→      Votes = 0,
118→    };
119→  }
120→
121→  /// <summary>
122→  /// Removes a task by its index from the specified column's task list.
123→  /// </summary>
124→  public void RemoveTask(AutomergeObjectId tasksListId, ulong index)
125→  {
126→    ThrowIfDisposed();
127→    _document.ListRemove(tasksListId, index);
128→    _document.Commit($"Remove task at {index}");
129→  }
130→
131→  /// <summary>
132→  /// Moves a task from one column to another by removing and re-inserting.
133→  /// </summary>
134→  public TaskItem MoveTask(
135→    AutomergeObjectId sourceTasksListId,
136→    ulong sourceIndex,
137→    AutomergeObjectId destTasksListId,
138→    ulong destIndex,
139→    TaskItem task)
140→  {
141→    ThrowIfDisposed();
142→
143→    // Remove from source
144→    _document.ListRemove(sourceTasksListId, sourceIndex);
145→
146→    // Insert into destination as a new map with the same data
147→    var newTaskId = _document.ListInsertObject(destTasksListId, destIndex, AutomergeContainerType.Map);
148→    _document.PutString(newTaskId, "title", task.Title);
149→    _document.PutString(newTaskId, "description", task.Description);
150→    _document.PutString(newTaskId, "status", task.Status);
151→    _document.PutCounter(newTaskId, "votes", task.Votes);
152→    _document.Commit($"Move task: {task.Title}");
153→
154→    return new TaskItem
155→    {
156→      ObjectId = newTaskId,
157→      Title = task.Title,
158→      Description = task.Description,
159→      Status = task.Status,
160→      Votes = task.Votes,
161→    };
162→  }
163→
164→  /// <summary>
165→  /// Increments the vote counter on a task.
166→  /// </summary>
167→  public void IncrementVotes(AutomergeObjectId taskId, long delta = 1)
168→  {
169→    ThrowIfDisposed();
170→    _document.Increment(taskId, "votes", delta);
171→    _document.Commit("Vote");
172→  }
173→
174→  /// <summary>
175→  /// Updates a task's title.
176→  /// </summary>
177→  public void UpdateTaskTitle(AutomergeObjectId taskId, string newTitle)
178→  {
179→    ThrowIfDisposed();
180→    _document.PutString(taskId, "title", newTitle);
181→    _document.Commit($"Update task title: {newTitle}");
182→  }
183→
184→  /// <summary>
185→  /// Updates a task's status.
186→  /// </summary>
187→  public void UpdateTaskStatus(AutomergeObjectId taskId, string newStatus)
188→  {
189→    ThrowIfDisposed();
190→    _document.PutString(taskId, "status", newStatus);
191→    _document.Commit($"Update task status: {newStatus}");
192→  }
193→
194→  /// <summary>
195→  /// Reads the full board state from the document.
196→  /// </summary>
197→  public List<Column> ReadBoard()
198→  {
199→    ThrowIfDisposed();
200→    var columns = new List<Column>();
201→    ulong columnCount = _document.ListLength(_columnsListId);
202→
203→    for(ulong i = 0; i < columnCount; i++)
204→    {
205→      var columnId = _document.ListGetObject(_columnsListId, i);
206→      if(columnId is null)
207→      {
208→        continue;
209→      }
210→
211→      var tasksListId = _document.GetObject(columnId, "tasks");
212→      if(tasksListId is null)
213→      {
214→        continue;
215→      }
216→
217→      var column = new Column
218→      {
219→        ObjectId = columnId,
220→        TasksListId = tasksListId,
221→        Name = _document.GetString(columnId, "name") ?? string.Empty,
222→        Order = _document.GetInt64(columnId, "order") ?? 0,
223→      };
224→
225→      ulong taskCount = _document.ListLength(tasksListId);
226→      for(ulong j = 0; j < taskCount; j++)
227→      {
228→        var taskId = _document.ListGetObject(tasksListId, j);
229→        if(taskId is null)
230→        {
231→          continue;
232→        }
233→
234→        column.Tasks.Add(new TaskItem
235→        {
236→          ObjectId = taskId,
237→          Title = _document.GetString(taskId, "title") ?? string.Empty,
238→          Description = _document.GetString(taskId, "description") ?? string.Empty,
239→          Status = _document.GetString(taskId, "status") ?? string.Empty,
240→          Votes = _document.GetCounter(taskId, "votes") ?? 0,
241→        });
242→      }
243→
244→      columns.Add(column);
245→    }
246→
247→    return columns;
248→  }
249→
250→  /// <summary>
251→  /// Seeds default columns ("To Do", "In Progress", "Done") into the document.
252→  /// </summary>
253→  public List<Column> SeedDefaultColumns()
254→  {
255→    ThrowIfDisposed();
256→    string[] names = ["To Do", "In Progress", "Done"];
257→    var columns = new List<Column>(names.Length);
258→    foreach(string name in names)
259→    {
260→      columns.Add(AddColumn(name));
261→    }
262→
263→    return columns;
264→  }
265→
266→  /// <summary>
267→  /// Saves the full document state as a byte array.
268→  /// </summary>
269→  public byte[] Save()
270→  {
271→    ThrowIfDisposed();
272→    return _document.Save();
273→  }
274→
275→  /// <summary>
276→  /// Loads a board from a previously saved byte array.
277→  /// </summary>
278→  public static AutomergeService Load(byte[] data)
279→  {
280→    var doc = AutomergeDocument.Load(data);
281→    var columnsListId = doc.GetObject(doc.RootId, "columns")
282→      ?? throw new InvalidOperationException("Saved document does not contain a 'columns' list.");
283→
284→    return new AutomergeService(doc, columnsListId, ownsDocument: true);
285→  }
286→
287→  /// <summary>
288→  /// Creates an AutomergeService that wraps an existing document.
289→  /// The document is NOT owned (not disposed by this service).
290→  /// </summary>
291→  public static AutomergeService FromDocument(AutomergeDocument document)
292→  {
293→    ArgumentNullException.ThrowIfNull(document);
294→
295→    var keys = document.GetKeys(document.RootId).ToList();
296→    AutomergeObjectId columnsListId;
297→
298→    if(keys.Contains("columns"))
299→    {
300→      columnsListId = document.GetObject(document.RootId, "columns")
301→        ?? throw new InvalidOperationException("Could not resolve 'columns' list object.");
302→    }
303→    else
304→    {
305→      columnsListId = document.PutObject(document.RootId, "columns", AutomergeContainerType.List);
306→      document.Commit("Initialize board columns");
307→    }
308→
309→    return new AutomergeService(document, columnsListId, ownsDocument: false);
310→  }
311→
312→  /// <summary>
313→  /// Gets the JSON representation of the document.
314→  /// </summary>
315→  public string HydrateJson()
316→  {
317→    ThrowIfDisposed();
318→    return _document.HydrateJson();
319→  }
320→
321→  public void Dispose()
322→  {
323→    if(!_disposed)
324→    {
325→      _disposed = true;
326→      if(_ownsDocument)
327→      {
328→        _document.Dispose();
329→      }
330→    }
331→  }
332→
333→  void ThrowIfDisposed()
334→  {
335→    ObjectDisposedException.ThrowIf(_disposed, this);
336→  }
337→}
