  3→namespace Ray.Automerge.Repository;
  4→
  5→/// <summary>
  6→/// C# port of the Automerge Repo <c>DocHandle&lt;T&gt;</c> API.
  7→/// </summary>
  8→[PublicAPI]
  9→public sealed class DocHandle<T> : IDocHandle
 10→{
 11→  readonly SemaphoreSlim _documentLock = new(1, 1);
 12→  readonly TaskCompletionSource<AutomergeDocument> _readySource =
 13→    new(TaskCreationOptions.RunContinuationsAsynchronously);
 14→  readonly List<byte[]> _pendingLocalChanges = [];
 15→  readonly object _stateGate = new();
 16→  readonly Func<AutomergeDocument, T> _viewFactory;
 17→  readonly TimeSpan _timeout;
 18→
 19→  AutomergeDocument? _document;
 20→  HandleState _state = HandleState.Idle;
 21→  IReadOnlyList<string> _currentHeads = [];
 22→  bool _isDisposed;
 23→  bool _isInitialized;
 24→  bool _isNewDocument;
 25→  IReadOnlyList<string>? _fixedHeads;
 26→
 27→  public DocHandle(
 28→    DocumentId documentId,
 29→    DocHandleOptions<T>? options = null,
 30→    AutomergeDocument? document = null)
 31→  {
 32→    DocumentId = documentId;
 33→    options ??= DocHandleOptions<T>.Default;
 34→
 35→    _timeout = options.Timeout;
 36→    _viewFactory = options.ViewFactory ?? DefaultViewFactory;
 37→    _fixedHeads = options.Heads;
 38→    _isNewDocument = options.IsNew;
 39→
 40→    if(document is not null)
 41→    {
 42→      Initialize(document, options.IsNew);
 43→    }
 44→  }
 45→
 46→  #region Events
 47→
 48→  public event EventHandler<DocHandleReadyEventArgs<T>>? Ready;
 49→
 50→  public event EventHandler<DocHandleChangeEventArgs<T>>? Changed;
 51→
 52→  public event EventHandler<DocHandleHeadsChangedEventArgs<T>>? HeadsChanged;
 53→
 54→  public event EventHandler<DocHandleDeletedEventArgs<T>>? Deleted;
 55→
 56→  public event EventHandler<DocHandleUnavailableEventArgs<T>>? Unavailable;
 57→
 58→  public event EventHandler<DocHandleRemoteHeadsEventArgs<T>>? RemoteHeadsUpdated;
 59→
 60→  public event EventHandler<DocHandleEphemeralMessageEventArgs<T>>? EphemeralMessageReceived;
 61→
 62→  public event EventHandler<DocHandleEphemeralMessageEventArgs<T>>? EphemeralMessageOutbound;
 63→
 64→  #endregion
 65→
 66→  #region Properties
 67→
 68→  public DocumentId DocumentId { get; }
 69→
 70→  public HandleState State
 71→  {
 72→    get
 73→    {
 74→      lock(_stateGate)
 75→      {
 76→        return _state;
 77→      }
 78→    }
 79→  }
 80→
 81→  public bool IsReady => State == HandleState.Ready;
 82→
 83→  public bool IsUnloaded => State == HandleState.Unloaded;
 84→
 85→  public bool IsDeleted => State == HandleState.Deleted;
 86→
 87→  public bool IsUnavailable => State == HandleState.Unavailable;
 88→
 89→  public bool IsReadOnly => _fixedHeads is not null;
 90→
 91→  public IReadOnlyList<string> Heads => Volatile.Read(ref _currentHeads);
 92→
 93→  #endregion
 94→
 95→  #region Lifecycle
 96→
 97→  public void Begin()
 98→  {
 99→    lock(_stateGate)
100→    {
101→      EnsureNotDisposed();
102→      if(_state == HandleState.Idle)
103→      {
104→        _state = HandleState.Loading;
105→      }
106→    }
107→  }
108→
109→  public void Initialize(AutomergeDocument document, bool isNewDocument = false)
110→  {
111→    ArgumentNullException.ThrowIfNull(document);
112→    EnsureNotDisposed();
113→
114→    lock(_stateGate)
115→    {
116→      if(_isInitialized)
117→      {
118→        throw new InvalidOperationException($"DocHandle '{DocumentId}' is already initialized.");
119→      }
120→
121→      _document = document;
122→      _isInitialized = true;
123→      _isNewDocument = isNewDocument;
124→      _state = HandleState.Ready;
125→      UpdateCachedHeads(document.GetHeads());
126→      _readySource.TrySetResult(document);
127→    }
128→
129→    Ready?.Invoke(this, new DocHandleReadyEventArgs<T>(this, isNewDocument));
130→  }
131→
132→  public void DoneLoading()
133→  {
134→    lock(_stateGate)
135→    {
136→      if(_state == HandleState.Loading || _state == HandleState.Requesting)
137→      {
138→        _state = HandleState.Ready;
139→      }
140→    }
141→  }
142→
143→  public void Request()
144→  {
145→    lock(_stateGate)
146→    {
147→      if(_state == HandleState.Loading)
148→      {
149→        _state = HandleState.Requesting;
150→      }

150→      }
151→    }
152→  }
153→
154→  public void MarkUnavailable()
155→  {
156→    lock(_stateGate)
157→    {
158→      _state = HandleState.Unavailable;
159→    }
160→
161→    Unavailable?.Invoke(this, new DocHandleUnavailableEventArgs<T>(this));
162→  }
163→
164→  public void Unload()
165→  {
166→    lock(_stateGate)
167→    {
168→      _state = HandleState.Unloaded;
169→      _document = null;
170→      _currentHeads = Array.Empty<string>();
171→    }
172→  }
173→
174→  public void Reload()
175→  {
176→    lock(_stateGate)
177→    {
178→      if(_state == HandleState.Unloaded)
179→      {
180→        _state = HandleState.Loading;
181→      }
182→    }
183→  }
184→
185→  public void Delete()
186→  {
187→    lock(_stateGate)
188→    {
189→      _state = HandleState.Deleted;
190→    }
191→
192→    Deleted?.Invoke(this, new DocHandleDeletedEventArgs<T>(this));
193→  }
194→
195→  public void Dispose()
196→  {
197→    if(Interlocked.Exchange(ref _isDisposed, true))
198→    {
199→      return;
200→    }
201→
202→    AutomergeDocument? document;
203→    lock(_stateGate)
204→    {
205→      document = _document;
206→      _document = null;
207→      _state = HandleState.Unloaded;
208→      _currentHeads = Array.Empty<string>();
209→      _pendingLocalChanges.Clear();
210→    }
211→
212→    document?.Dispose();
213→    _documentLock.Dispose();
214→    _readySource.TrySetCanceled();
215→  }
216→
217→  #endregion
218→
219→  #region Document access
220→
221→  public async ValueTask<T> DocAsync(CancellationToken cancellationToken = default)
222→  {
223→    var doc = await WaitForDocumentAsync(cancellationToken).ConfigureAwait(false);
224→    return _viewFactory(doc);
225→  }
226→
227→  public T Doc()
228→  {
229→    var doc = Volatile.Read(ref _document);
230→    if(doc is null)
231→    {
232→      throw new InvalidOperationException($"DocHandle '{DocumentId}' is not ready. Await WhenReadyAsync before calling Doc().");
233→    }
234→
235→    return _viewFactory(doc);
236→  }
237→
238→  public T DocSync() => Doc();
239→
240→  /// <summary>
241→  /// Gets the underlying Automerge document (non-generic IDocHandle implementation).
242→  /// </summary>
243→  AutomergeDocument? IDocHandle.GetDocument() => _document;
244→
245→  public Task WhenReadyAsync(CancellationToken cancellationToken = default) =>
246→    WaitForDocumentAsync(cancellationToken).AsTask();
247→
248→  public async ValueTask<TResult> ReadAsync<TResult>(
249→    Func<AutomergeDocument, TResult> reader,
250→    CancellationToken cancellationToken = default)
251→  {
252→    ArgumentNullException.ThrowIfNull(reader);
253→    EnsureReady();
254→
255→    var document = await WaitForDocumentAsync(cancellationToken).ConfigureAwait(false);
256→
257→    await _documentLock.WaitAsync(cancellationToken).ConfigureAwait(false);
258→    try
259→    {
260→      EnsureNotDisposed();
261→      return reader(document);
262→    }
263→    finally
264→    {
265→      _documentLock.Release();
266→    }
267→  }
268→
269→  public async ValueTask ReadAsync(
270→    Action<AutomergeDocument> reader,
271→    CancellationToken cancellationToken = default)
272→  {
273→    ArgumentNullException.ThrowIfNull(reader);
274→    EnsureReady();
275→
276→    var document = await WaitForDocumentAsync(cancellationToken).ConfigureAwait(false);
277→
278→    await _documentLock.WaitAsync(cancellationToken).ConfigureAwait(false);
279→    try
280→    {
281→      EnsureNotDisposed();
282→      reader(document);
283→    }
284→    finally
285→    {
286→      _documentLock.Release();
287→    }
288→  }
289→
290→  public IReadOnlyList<string> GetHeads()
291→  {
292→    EnsureReady();
293→    return Heads;
294→  }
295→
296→  public IReadOnlyList<IReadOnlyList<string>> History()
297→  {
298→    EnsureReady();
299→
300→    return ReadAsync(static doc =>
301→    {
302→      var hashes = doc.TopoHistoryTraversal();
303→      if(hashes.Count == 0)
304→      {
305→        return [];
306→      }
307→
308→      return hashes
309→        .Select(hash => (IReadOnlyList<string>)[hash])
310→        .ToArray();
311→    }).GetAwaiter().GetResult();
312→  }
