314→  public DocHandle<T> View(IReadOnlyList<string> heads)
315→  {
316→    if(heads is null)
317→      throw new ArgumentNullException(nameof(heads));
318→
319→    if(heads.Count == 0)
320→      throw new ArgumentException("Heads cannot be empty.", nameof(heads));
321→
322→    EnsureReady();
323→
324→    // Clone the document by saving and loading
325→    var documentData = ReadAsync(doc => doc.Save()).GetAwaiter().GetResult();
326→    var clonedDoc = AutomergeDocument.Load(documentData);
327→
328→    // Isolate the clone to the specified heads
329→    clonedDoc.Isolate(heads);
330→
331→    // Create a new read-only handle with fixed heads
332→    var viewHandle = new DocHandle<T>(
333→      DocumentId,
334→      new DocHandleOptions<T>
335→      {
336→        IsNew = false,
337→        Heads = heads,
338→        Timeout = _timeout,
339→        ViewFactory = _viewFactory
340→      },
341→      clonedDoc);
342→
343→    return viewHandle;
344→  }
