593→  /// <summary>
594→  /// Notifies the handle that the document was updated externally (e.g., by sync protocol).
595→  /// Updates cached heads and triggers change events.
596→  /// </summary>
597→  internal void NotifyRemoteChange(AutomergeDocument document)
598→  {
599→    EnsureNotDisposed();
600→    if(_state != HandleState.Ready)
601→    {
602→      return;
603→    }
604→
605→    UpdateCachedHeads(document.GetHeads());
606→    OnChanged(null, isLocal: false, null);
607→  }
