609→  public void Merge(DocHandle<T> other)
610→  {
611→    if(other is null)
612→    {
613→      throw new ArgumentNullException(nameof(other));
614→    }
615→
616→    EnsureEditable();
617→
618→    using var mergeLock = new CompositeSemaphore(_documentLock, other._documentLock);
619→
620→    var doc = DocInternal();
621→    var otherDoc = other.DocInternal();
622→
623→    var hashes = doc.Merge(otherDoc);
624→    if(hashes.Count > 0)
625→    {
626→      UpdateCachedHeads(doc.GetHeads());
627→      OnChanged(null, isLocal: true, null);
628→    }
629→  }
630→
631→  public IReadOnlyList<byte[]> DrainLocalChanges()
632→  {
633→    EnsureReady();
634→
635→    lock(_stateGate)
636→    {
637→      if(_pendingLocalChanges.Count == 0)
638→      {
639→        return Array.Empty<byte[]>();
640→      }
641→
642→      var drained = _pendingLocalChanges
643→        .Select(change => change.ToArray())
644→        .ToArray();
645→
646→      _pendingLocalChanges.Clear();
647→      return new ReadOnlyCollection<byte[]>(drained);
648→    }
649→  }
