687→  ValueTask<AutomergeDocument> WaitForDocumentAsync(CancellationToken cancellationToken)
688→  {
689→    EnsureNotDisposed();
690→
691→    var existing = Volatile.Read(ref _document);
692→    if(existing is not null)
