700→  void OnChanged(DocLocalChange<T>? localChange, bool isLocal, IReadOnlyList<byte[]>? appliedChanges)
701→  {
702→    if(localChange is not null)
703→    {
704→      HeadsChanged?.Invoke(this, new DocHandleHeadsChangedEventArgs<T>(this, Heads));
705→    }
706→    else if(appliedChanges is not null)
707→    {
708→      HeadsChanged?.Invoke(this, new DocHandleHeadsChangedEventArgs<T>(this, Heads));
709→    }
710→
711→    var doc = Volatile.Read(ref _document);
712→    if(doc is null)
713→    {
714→      return;
715→    }
716→
717→    Changed?.Invoke(
718→      this,
719→      new DocHandleChangeEventArgs<T>(
720→        this,
721→        _viewFactory(doc),
722→        isLocal,
723→        localChange,
724→        appliedChanges));
725→  }
