727→  void UpdateCachedHeads(IReadOnlyList<string> heads)
728→  {
729→    var copy = heads.Count == 0
730→      ? (IReadOnlyList<string>)Array.Empty<string>()
731→      : new ReadOnlyCollection<string>(heads.ToArray());
732→
733→    Volatile.Write(ref _currentHeads, copy);
