762→  static T DefaultViewFactory(AutomergeDocument doc)
763→  {
764→    if(typeof(T) == typeof(AutomergeDocument))
765→    {
766→      return (T)(object)doc;
767→    }
768→
769→    throw new InvalidOperationException(
770→      $"Provide a view factory when constructing DocHandle<{typeof(T).Name}> so the document can be projected.");
