775→  sealed class CompositeSemaphore : IDisposable
776→  {
777→    readonly SemaphoreSlim _first;
778→    readonly SemaphoreSlim _second;
779→
780→    public CompositeSemaphore(SemaphoreSlim first, SemaphoreSlim second)
781→    {
782→      _first = first;
783→      _second = second;
784→
785→      _first.Wait();
786→      if(!ReferenceEquals(first, second))
787→      {
788→        _second.Wait();
789→      }
790→    }
791→
792→    public void Dispose()
793→    {
794→      _second.Release();
795→      _first.Release();
796→    }
797→  }
798→}
