using Ray.Automerge.Repository.Network.SignalR.Server;
using Ray.Automerge.Repository.Network.SignalR.Server.Extensions;

var builder = WebApplication.CreateBuilder(args);

// Add service defaults (includes service discovery, health checks, etc.)
builder.AddServiceDefaults();

// Add SignalR DocumentsHub with MessagePack + JSON protocols
builder.Services.AddSignalRDocumentsHub();

builder.Services
  .AddCors(options =>
  {
    options.AddPolicy("AllowAll", policy =>
    {
      policy
        .SetIsOriginAllowed(_ => true)
        .AllowAnyMethod()
        .AllowAnyHeader()
        .AllowCredentials();
    });
  });

if(builder.Environment.IsDevelopment())
{
  builder.Services.AddOpenApi();
}

var app = builder.Build();

app.UseHttpsRedirection();
app.UseCors("AllowAll");

app.MapDefaultEndpoints();

// Map the SignalR documents hub
app.MapHub<DocumentsHub>("/hubs/documents");

// Hub health check endpoint
app.MapGet("/hubs/health", () => Results.Ok(new { status = "healthy", hub = "/hubs/documents" }));

if(app.Environment.IsDevelopment())
{
  app.MapOpenApi();
}

await app.RunAsync();

