  1→using Ray.Automerge.Repository.Network;
  2→
  3→namespace Ray.Automerge.Repository.Synchronizer;
  4→
  5→/// <summary>
  6→/// Manages synchronization for all documents in a repository.
  7→/// Routes messages to appropriate DocSynchronizers and enforces policies.
  8→/// </summary>
  9→[PublicAPI]
 10→public sealed class CollectionSynchronizer : IDisposable
 11→{
 12→  readonly Dictionary<string, DocSynchronizer> _docSynchronizers = [];
 13→  readonly HashSet<PeerId> _connectedPeers = [];
 14→  readonly SemaphoreSlim _lock = new(1, 1);
 15→  readonly ISet<string> _denylist;
 16→
 17→  Func<DocumentId, PeerId, Task<bool>>? _sharePolicy;
 18→  Func<DocumentId, PeerId, Task<bool>>? _accessPolicy;
 19→  readonly Func<string, AutomergeDocument?> _getDocument;
 20→  readonly Action<string, AutomergeDocument> _updateDocument;
 21→  readonly Func<PeerId, PeerMetadata?> _getPeerMetadata;
 22→  readonly Action<string> _requestDocument;
 23→
 24→  bool _isDisposed;
 25→
 26→  /// <summary>
 27→  /// Event fired when a message should be sent to a peer.
 28→  /// </summary>
 29→  public event EventHandler<SyncMessageEventArgs>? MessageToSend;
 30→
 31→  /// <summary>
 32→  /// Event fired when sync state changes (for persistence).
 33→  /// </summary>
 34→  public event EventHandler<SyncStateChangedEventArgs>? SyncStateChanged;
 35→
 36→  /// <summary>
 37→  /// Event fired when sync metrics are updated.
 38→  /// </summary>
 39→  public event EventHandler<SyncMetricsEventArgs>? MetricsUpdated;
 40→
 41→  /// <summary>
 42→  /// Event fired when a document is unavailable from all peers.
 43→  /// </summary>
 44→#pragma warning disable CS0067 // Event is never used - will be used in future implementation
 45→  public event EventHandler<DocumentUnavailableEventArgs>? DocumentUnavailable;
 46→#pragma warning restore CS0067
 47→
 48→
 49→  /// <summary>
 50→  /// Creates a new CollectionSynchronizer.
 51→  /// </summary>
 52→  /// <param name="getDocument">Callback to retrieve a document by ID</param>
 53→  /// <param name="updateDocument">Callback to update a document after receiving changes</param>
 54→  /// <param name="getPeerMetadata">Callback to retrieve peer metadata</param>
 55→  /// <param name="requestDocument">Callback to request a document (for discovery)</param>
 56→  /// <param name="denylist">Optional set of document IDs to never sync</param>
 57→  public CollectionSynchronizer(
 58→    Func<string, AutomergeDocument?> getDocument,
 59→    Action<string, AutomergeDocument> updateDocument,
 60→    Func<PeerId, PeerMetadata?> getPeerMetadata,
 61→    Action<string> requestDocument,
 62→    ISet<string>? denylist = null)
 63→  {
 64→    _getDocument = getDocument ?? throw new ArgumentNullException(nameof(getDocument));
 65→    _updateDocument = updateDocument ?? throw new ArgumentNullException(nameof(updateDocument));
 66→    _getPeerMetadata = getPeerMetadata ?? throw new ArgumentNullException(nameof(getPeerMetadata));
 67→    _requestDocument = requestDocument ?? throw new ArgumentNullException(nameof(requestDocument));
 68→    _denylist = denylist ?? new HashSet<string>();
 69→  }
 70→
 71→
 72→  /// <summary>
 73→  /// Registers a document for synchronization with all connected peers.
 74→  /// </summary>
 75→  public void AddDocument(string documentId)
 76→  {
 77→    if(string.IsNullOrWhiteSpace(documentId))
 78→      throw new ArgumentException("Document ID cannot be null or whitespace", nameof(documentId));
 79→
 80→    ThrowIfDisposed();
 81→
 82→    if(IsInDenylist(documentId)) return;
 83→
 84→    // Collect deferred operations
 85→    DocSynchronizer? docSync;
 86→    var peersToSync = new List<PeerId>();
 87→
 88→    _lock.Wait();
 89→    try
 90→    {
 91→      docSync = GetOrCreateDocSync(documentId);
 92→
 93→      // Collect peers to sync with
 94→      foreach(var peer in _connectedPeers)
 95→      {
 96→        // Check share policy
 97→        // Note: GetAwaiter().GetResult() is used here because AddDocument is called from sync contexts.
 98→        // The share policy is async but must be evaluated synchronously to maintain the sync API.
 99→        // This is internal implementation and doesn't affect the public API.
100→        if(ShouldShare(documentId, peer).GetAwaiter().GetResult())
101→        {
102→          peersToSync.Add(peer);
103→        }
104→      }
105→    }
106→    finally
107→    {
108→      _lock.Release();
109→    }
110→
111→    // Begin syncing outside the lock to prevent deadlocks
112→    foreach(var peer in peersToSync)
113→    {
114→      docSync.BeginSync(peer);
115→    }
116→  }
117→
118→  /// <summary>
119→  /// Unregisters a document from synchronization.
120→  /// </summary>
121→  public void RemoveDocument(string documentId)
122→  {
123→    ThrowIfDisposed();
124→
125→    _lock.Wait();
126→    try
127→    {
128→      if(_docSynchronizers.TryGetValue(documentId, out var docSync))
129→      {
130→        docSync.Dispose();
131→        _docSynchronizers.Remove(documentId);
132→      }
133→    }
134→    finally
135→    {
136→      _lock.Release();
137→    }
138→  }
139→
140→  /// <summary>
141→  /// Called when a new peer connects. Begins syncing all documents with this peer.
142→  /// </summary>
143→  public void OnPeerConnected(PeerId peerId)
144→  {
145→    ThrowIfDisposed();
146→
147→    // Collect deferred operations
148→    var docsToSync = new List<(string documentId, DocSynchronizer docSync)>();
149→
150→    _lock.Wait();
151→    try
152→    {
153→      if(_connectedPeers.Contains(peerId)) return;
154→
155→      _connectedPeers.Add(peerId);
156→
157→      // Collect documents to sync with this peer
158→      foreach(var (documentId, docSync) in _docSynchronizers)
159→      {
160→        // Check share policy
161→        // Note: GetAwaiter().GetResult() is used here because OnPeerCandidate is called from sync network contexts.
162→        // The share policy is async but must be evaluated synchronously to maintain internal API consistency.
163→        // This is internal implementation and doesn't affect the public API.
164→        if(ShouldShare(documentId, peerId).GetAwaiter().GetResult())
165→        {
166→          docsToSync.Add((documentId, docSync));
167→        }
168→      }
169→    }
170→    finally
171→    {
172→      _lock.Release();
173→    }
174→
175→    // Begin syncing outside the lock to prevent deadlocks
176→    foreach(var (documentId, docSync) in docsToSync)
177→    {
178→      docSync.BeginSync(peerId);
179→    }
180→  }
181→
182→  /// <summary>
183→  /// Called when a peer disconnects. Cleans up sync state for this peer.
184→  /// </summary>
185→  public void OnPeerDisconnected(PeerId peerId)
186→  {
187→    ThrowIfDisposed();
188→
189→    _lock.Wait();
190→    try
191→    {
192→      _connectedPeers.Remove(peerId);
193→
194→      // End sync for all documents
195→      foreach(var docSync in _docSynchronizers.Values)
196→      {
197→        docSync.EndSync(peerId);
198→      }
199→    }
200→    finally
201→    {
202→      _lock.Release();
203→    }
204→  }
205→
206→  /// <summary>
207→  /// Routes incoming message to appropriate DocSynchronizer.
208→  /// Handles document discovery for unknown documents.
209→  /// </summary>
210→  public void OnMessageReceived(IRepoMessage message)
211→  {
212→    ThrowIfDisposed();
213→
214→    if(message is null) return;
215→    if(message.SenderId is null) return; // Must have sender
216→    var documentIdValue = message.DocumentId?.Value;
217→    if(documentIdValue is null) return; // Must have document ID
218→
219→    var documentId = documentIdValue;
220→    var senderId = message.SenderId.Value;
221→
222→    // Check denylist
223→    if(IsInDenylist(documentId)) return;
224→
225→    // Check access policy
226→    // Note: GetAwaiter().GetResult() is used here because OnMessageReceived is called from sync network contexts.
227→    // The access policy is async but must be evaluated synchronously to maintain internal API consistency.
228→    // This is internal implementation and doesn't affect the public API.
229→    if(!CanAccess(documentId, senderId).GetAwaiter().GetResult())
230→    {
231→      // Access denied, don't process message
232→      return;
233→    }
234→
235→    DocSynchronizer? docSync;
236→    bool needsBeginSync = false;
237→
238→    _lock.Wait();
239→    try
240→    {
241→      // Get or create doc synchronizer
242→      docSync = GetOrCreateDocSync(documentId);
243→
244→      // If this is a new document we discovered, request it
245→      var doc = _getDocument(documentId);
246→      if(doc is null && !docSync.HasPeer(senderId))
247→      {
248→        // We don't have this document, trigger discovery
249→        _requestDocument(documentId);
250→      }
251→
252→      // Check if peer needs to be tracked
253→      if(!docSync.HasPeer(senderId))
254→      {
255→        needsBeginSync = true;
256→      }
257→    }
258→    finally
259→    {
260→      _lock.Release();
261→    }
262→
263→    // Begin sync outside the lock to prevent deadlocks
264→    if(needsBeginSync)
265→    {
266→      docSync.BeginSync(senderId);
267→    }
268→
269→    // Process message (outside lock to prevent deadlocks)
270→    docSync.ReceiveMessage(message, senderId);
271→  }
272→
273→  /// <summary>
274→  /// Notifies the synchronizer that a local document change occurred.
275→  /// </summary>
276→  /// <param name="documentId">The document identifier.</param>
277→  public void NotifyDocumentChanged(string documentId)
278→  {
279→    ThrowIfDisposed();
280→
281→    DocSynchronizer? docSync;
282→
