176→  {
177→    ThrowIfDisposed();
178→
179→    _messagesReceived++;
180→
181→    // Collect events to fire after releasing lock
182→    var deferredEvents = new List<Action>();
183→
184→    _lock.Wait();
185→    try
186→    {
187→      switch(message)
188→      {
189→        case SyncMessage sync:
