191→          break;
192→
193→        case RequestMessage request:
194→          ReceiveRequestMessage(request, senderId, deferredEvents);
195→          break;
196→
197→        case DocumentUnavailableMessage unavail:
198→          ReceiveDocumentUnavailable(unavail, senderId);
199→          break;
200→        case DocumentSnapshotMessage snapshot:
201→          ReceiveDocumentSnapshot(snapshot, senderId);
202→          break;
203→
204→        default:
205→          // Unknown message type, ignore
206→          break;
207→      }
208→    }
209→    finally
210→    {
211→      _lock.Release();
212→    }
213→
214→    // Fire all deferred events after releasing the lock
215→    foreach(var eventAction in deferredEvents)
216→    {
217→      eventAction();
218→    }
219→  }
