221→  /// <summary>
222→  /// Processes incoming sync message using Automerge sync protocol.
223→  /// </summary>
224→  private void ReceiveSyncMessage(SyncMessage message, PeerId senderId, List<Action> deferredEvents,
225→    bool preserveWantsStatus = false)
226→  {
227→    Console.WriteLine($"[DocSync] Received SyncMessage for document {_documentId} from peer {senderId} (data length: {message.Data?.Length ?? 0})");
228→    // Validate message data
229→    if(message.Data is null)
230→    {
231→      Console.Error.WriteLine($"Received null sync message data for document {_documentId} from peer {senderId}");
232→      return;
233→    }
234→
235→    // Get document (or create empty one if we don't have it yet)
236→    var doc = _getDocument();
237→    var isNewDocument = doc is null;
238→    if(doc is null)
239→    {
240→      Console.WriteLine($"[DocSync] Document {_documentId} not found locally, creating empty document to receive sync data");
241→      // We don't have the document yet, but the peer is sending us data
242→      // Create an empty document to receive the sync data
243→      doc = AutomergeDocument.Create();
244→    }
245→
246→    // Get sync state for this peer
247→    var syncState = GetOrCreateSyncState(senderId);
248→
249→    var shouldRespond = true;
250→
251→    try
252→    {
253→      // Apply sync message using Automerge protocol
254→      // Note: Empty messages are valid in the sync protocol (they indicate "I have nothing new")
255→      // Note: The current API mutates both doc and syncState in place
256→      if(message.Data.Length > 0)
257→      {
258→        doc.ReceiveSyncMessage(syncState, message.Data);
259→
260→        Console.WriteLine($"[DocSync] Post-merge state for document {_documentId} after receiving from {senderId}: {doc.HydrateJson()}");
261→
262→        // Notify owner that document was updated
263→        _updateDocument(doc);
264→      }
265→      else if(isNewDocument)
266→      {
267→        // No payload but we created a local document instance; ensure repo registers it.
268→        _updateDocument(doc);
269→        // Nothing additional to send back unless we still owe data (e.g., due to request).
270→        if(!preserveWantsStatus)
271→        {
272→          shouldRespond = false;
273→        }
274→      }
275→
276→      // Mark peer as having the document (unless we need to preserve Wants status from RequestMessage)
277→      if(!preserveWantsStatus || _peerStatuses[senderId] != PeerDocumentStatus.Wants)
278→      {
279→        _peerStatuses[senderId] = PeerDocumentStatus.Has;
280→      }
281→
